INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000000335', 'radical', '華', 'showy', 41, 0, 'Radikal ini sama dengan kanji. Artinya mencolok.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000381', 'radical', '夆', 'signpost', 41, 0, 'Ini adalah postingan dengan tanda di atasnya. Dan di atasnya ada penanda musim dingin, yang menunjukkan bahwa jika Anda pergi ke utara, di sana sedang musim dingin. Tanda-tandanya bertuliskan "Narnia ↑" dan "Meridell ←" dan "Bananaland →" sehingga Anda tahu itu adalah penunjuk arah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000384', 'radical', '瓜', 'melon', 42, 0, 'Ini melon. Bayangkan sebuah melon dipotong menjadi dua, dan Anda melihat bagian dalamnya dari samping. Lihat bagian melon pribadi yang berharga itu? Anda akan menyimpannya untuk diri Anda sendiri, karena melon itu enak dan tidak untuk dibagikan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000385', 'radical', '骨', 'bone', 42, 1, 'Radikal ini sama dengan kanji. Artinya tulang.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000386', 'radical', '臼', 'grenade-386', 42, 0, 'Ini adalah cangkang granat yang meledak. LEDAKAN! Itu meledak, membelahnya di tengah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000387', 'radical', '屋', 'shop', 42, 2, 'Kita sudah mempunyai akar kata radikal, jadi kita akan menggunakan arti kanji sekunder untuk kata radikal ini. Itu toko, ingat?', NULL, NULL),
  ('00000000-0000-4000-8000-000000000388', 'radical', '耒', 'plow', 43, 0, 'Anda menggeser tanah dengan pohon yang Anda tebang. Alat yang Anda buat ini disebut bajak. Gunakan untuk mendorong kotoran!', NULL, NULL),
  ('00000000-0000-4000-8000-000000000389', 'radical', '龍', 'imperial', 43, 1, 'Berdirilah di bulan sehingga Anda dapat memandang rendah negara Anda. Segala garis dan perbatasannya adalah perbatasan semua negara yang Anda kuasai, karena Anda adalah seorang kekaisaran.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000392', 'radical', '缶', 'can', 44, 0, 'Agak sulit untuk melihatnya, tetapi jika Anda melihatnya dengan benar, ini terlihat seperti kaleng. Garis di tengah menunjukkan keliling, dan garis di bagian atas dan samping menunjukkan garis luar kaleng.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000394', 'radical', '竜', 'dragon', 44, 1, 'Kura-kura yang berdiri bukan lagi kura-kura. Itu berevolusi menjadi monster. Monster macam apa? Seekor naga! mentah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000396', 'radical', '守', 'protect', 45, 0, 'Radikal ini sama dengan kanji. Artinya melindungi.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000397', 'radical', '更', 'again', 45, 1, 'Radikal ini sama dengan kanji. Artinya lagi.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000398', 'radical', '家', 'house', 45, 2, 'Radikal ini sama dengan kanji. Artinya rumah.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000400', 'radical', '恵', 'favor', 46, 0, 'Radikal ini sama dengan kanji. Itu berarti bantuan.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000401', 'radical', '務', 'task-401', 47, 0, 'Ini sama dengan Tugas kanji.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000402', 'radical', '波', 'wave', 47, 0, 'Radikal ini sama dengan kanji. Artinya gelombang.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000403', 'radical', '玄', 'mysterious', 48, 0, 'Apa yang ada di balik penutup ini yang berbau seperti kotoran? Aku tidak tahu! Sungguh misterius.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000404', 'radical', '容', 'form', 48, 1, 'Radikal ini sama dengan kanji. Artinya bentuk.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000405', 'radical', '光', 'sunlight', 48, 2, 'Radikal ini sama dengan kanji. Artinya sinar matahari.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000406', 'radical', '回', 'times', 49, 0, 'Radikal ini sama dengan kanji. Artinya kali.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000407', 'radical', '甚', 'crab-trap', 49, 1, 'Radikal ini terlihat seperti binatang kecil (匹) yang ada kepiting (其) yang mencuat di dalamnya. Seringkali ketika seekor kepiting sedang memakan hewan kecil, hewan kecil tersebut dimasukkan ke dalam perangkap kepiting untuk menangkap kepiting tersebut, dan memikatnya bersama hewan kecil tersebut. Itu sebabnya radikal ini adalah perangkap kepiting.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000409', 'radical', '名', 'name', 50, 0, 'Radikal ini sama dengan kanji. Artinya nama.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000410', 'radical', '禺', 'splinter', 50, 1, 'Meski sedikit dimodifikasi, ada cangkang kura-kura yang berkumis dengan radikal ini. Satu-satunya makhluk berkumis yang menjuntai di sekitar penyu adalah Splinter, tikus raksasa dari Teenage Mutant Ninja Turtles. Jadi radikal ini adalah Splinter (tikus raksasa).', NULL, NULL),
  ('00000000-0000-4000-8000-000000000411', 'radical', '太', 'fat', 46, 1, 'Radikal ini sama dengan kanji. Artinya gemuk.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000412', 'radical', '豸', 'badger', 43, 2, 'Anda tahu radikal hewan. Ini seperti itu dengan sedikit tambahan. Itu sudah binatang... artinya yang perlu Anda lakukan hanyalah mengingat jenis binatang apa. Dalam hal ini, itu adalah luak.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000416', 'radical', '風', 'wind', 44, 2, 'Radikal ini sama dengan kanji. Artinya angin.', NULL, NULL),
  ('00000000-0000-4000-8000-000000000431', 'radical', '敝', 'penguin', 47, 1, 'Ada sirip yang terbungkus handuk di musim dingin. Siapa yang mengeringkan sirip ikan ini untuk dimakan? Seekor penguin.', NULL, NULL),
  ('00000000-0000-4000-8000-000000001774', 'kanji', '遜', '遜', 41, 3, 'On this scooter is a child who''s trying to show that his lineage is humble. All of the other children are going around in fancy cars or helicopters, but this one child wants to be a humble child of the people, so he scoots on a plebeian scooter.', 'This humble child is your son (そん). You don''t want any child of yours flaunting his wealth and good standing in the faces of other people. You''ve taught them to be humble.', NULL),
  ('00000000-0000-4000-8000-000000001775', 'kanji', '伺', '伺', 41, 4, 'Your leader is also a director so you need to pay respects to him before you can start filming. He’s a huge big-shot and you don’t want to offend him by not paying the proper respects, so you make sure to bow every time you go on stage.', 'It turns out you''re filming Iron Chef, and the leader and director is Chairman Kaga. You pay respects to him by saying Ooh! Kaga (うかが).', NULL),
  ('00000000-0000-4000-8000-000000001776', 'kanji', '徹', '徹', 41, 5, 'You decide to loiter next to the trash under the moon in winter so the moon''s light will penetrate you. The sky is clearest in winter, and this spot next to the trash happens to get the most of it.', 'You want the light to penetrate you, so you put your face in the way of the beam and it shoots clear through you. Your mouth fills with the taste of 鉄 (てつ).', NULL),
  ('00000000-0000-4000-8000-000000001777', 'kanji', '瀬', '瀬', 41, 6, 'A tsunami hits a bundle of geoducks, swirling around their weird shapes, and creating rapids! The rapids are so violent, some of the geoducks break out of the bundle and get washed into the shallows.', 'After being washed through the rapids and into the shallows, the living geoducks are screaming “Save (せ) me! Save me!” They need to be saved from the water, and you are the only one who can save them. You gotta run over and help them out.', NULL),
  ('00000000-0000-4000-8000-000000001778', 'kanji', '撤', '撤', 41, 7, 'You use your fingers to dig through the trash in the light of the moon in winter because you''re going through withdrawal. You need your fix and you need it now, so you''re willing to freeze your fingers off digging through moonlit trash to get it.', 'The withdrawal makes you withdraw a 鉄 (てつ) and try to eat it. The taste of the 鉄 fills your entire mouth.', NULL),
  ('00000000-0000-4000-8000-000000001779', 'kanji', '措', '措', 41, 8, 'You find some fingers from long ago. They must have been set aside by their previous owners. They definitely weren''t cut off or anything, someone just decided they didn''t want them anymore and set them aside.', 'I know why they set aside their fingers long ago, it''s because there was no soap (そ). If you didn''t have soap to clean your fingers you wouldn''t want to keep them for very long...', NULL),
  ('00000000-0000-4000-8000-000000001780', 'kanji', '拠', '拠', 41, 9, 'Wipe your fingers on this table in winter to see what it was based on. The cold winter weathers cover the table in frost, and when you wipe it away, you can see traces of what the table was originally based on. All tables have to be based on something, even if it''s just other tables that came before them.', 'This particular table was based on Little Kyoto (きょ). Little buildings and temples, that sort of look like Little Kyoto. Problem is, it was made by a 子 (こ), so it''s not very good.', NULL),
  ('00000000-0000-4000-8000-000000001781', 'kanji', '儀', '儀', 41, 10, 'The leader of righteousness is the only one who can run this ceremony. Why? Because it''s a very pure ceremony, and only those with an extremely righteous mind can run it.', 'Sadly, the reason only the righteous can run this ceremony is because it''s a punishment ceremony, where he pulls the cord to cut someone''s head off via a guillotine (ぎ).', NULL),
  ('00000000-0000-4000-8000-000000001782', 'kanji', '樹', '樹', 41, 11, 'Each tree needs its drum measurement done before you can say it''s really made of wood.', 'If you''re still not sure if the tree is really made of wood, just take out a small juice (じゅ) box and start drinking it. A wooden tree will show no interest in the juice box at all.', NULL),
  ('00000000-0000-4000-8000-000000001783', 'kanji', '棄', '棄', 41, 12, 'In the trash is a weird looking fruit. Someone decided to abandon it here.', 'You reach into the trash, take out the abandoned fruit, and bite into it. OUCH! There''s a key (き) inside, and you just bit into it.', NULL),
  ('00000000-0000-4000-8000-000000001784', 'kanji', '虎', '虎', 41, 13, 'A tiger has legs that belong to a tiger. You know, a tiger has the legs of a tiger. This is common knowledge. Nothing new here.', 'The tiger is using his legs to run away from the Torah (とら). This tiger is deathly afraid of religion, so a holy book like the Torah causes the tiger to run away.', NULL),
  ('00000000-0000-4000-8000-000000001785', 'kanji', '蛍', '蛍', 41, 14, 'A Viking insect is a firefly. In the insect kingdom, the insect most resembling a Viking is undoubtedly the firefly.', 'The Viking firefly is attacking Hotaru (ほたる) Tomoe (alter ego of Sailor Saturn) because the Viking firefly hates the show Sailor Moon and everyone on it. Hotaru screams in terror as she is deathly afraid of fireflies, especially Viking ones.', NULL),
  ('00000000-0000-4000-8000-000000001786', 'kanji', '蜂', '蜂', 41, 15, 'On the insect signpost there is a single sign that says bee.', 'Thanks to the insect signpost you find the bee. You make it just in time to see the bee hatch (はち) from its egg.', NULL),
  ('00000000-0000-4000-8000-000000001787', 'kanji', '酎', '酎', 41, 16, 'The alcohol you take a measurement most carefully of is sake. Sake is very important to the alcohol culture in Japan, so you must make sure to measure it out to the precise amount.', 'You know who enjoyed sake a lot? Chewbacca (ちゅう). He was always drinking, which is concerning when you think about all the driving he did.', NULL),
  ('00000000-0000-4000-8000-000000001788', 'kanji', '蜜', '蜜', 41, 17, 'The roof (hive) on a certain insect (a bee) is what protects all of the honey.', 'To get the honey out, you need to put on special mitts (みつ) so your hands don''t get stung.', NULL),
  ('00000000-0000-4000-8000-000000001789', 'kanji', '墟', '墟', 41, 18, 'You''re digging in the dirt when you find a tiger and a cactus. You keep digging until you realize that these are a part of some big ruins. They''re the ruins of tiger and cactus statues. It looks like whoever used to live here worshiped tigers and cacti. Or maybe they ate them. But now their whole civilization is just ruins.', 'Well, as it turns out, these are the ruins of Little Kyoto (きょ), the city that existed before the modern day one. And it looks like the citizens of Little Kyoto faced their end a long time ago.', NULL),
  ('00000000-0000-4000-8000-000000001790', 'kanji', '艦', '艦', 41, 19, 'The boat that oversees other boats, land, and people is usually a warship. They''re the big boats that oversee everything around them. And if anyone steps out of line, a warship can take care of it.', 'This huge warship is run by Genghis Khan (かん), the famous warlord. Really, what did you expect? Who else is strong enough to captain a warship but him?', NULL),
  ('00000000-0000-4000-8000-000000001791', 'kanji', '潜', '潜', 41, 20, 'A tsunami carries a husband and his husband up into the sun where they conceal their centaur. The two husbands run a centaur farm, but the local government isn’t too pleased by this so they have to conceal their centaurs in the sun unless they want them to be confiscated by the government.', 'What is it the husbands are going to conceal? Oh that’s right, a centaur (せん). They are concealing a centaur in the sun. How forgetful of you.', NULL),
  ('00000000-0000-4000-8000-000000001792', 'kanji', '拳', '拳', 41, 21, 'A gladiator turns his hand into a fist. A fist for punching other gladiators.', 'The gladiator''s fist is now aimed at Ken (けん) the samurai. Little does the gladiator know, Ken knows the ways of the samurai and the gladiator. He slowly raises his own hands and turns them into fists.', NULL),
  ('00000000-0000-4000-8000-000000001793', 'kanji', '炭', '炭', 41, 22, 'You climb up a mountain and a cliff in search of fire, but all you find is charcoal. You can make fire with the charcoal, but you were hoping to find fire itself. All that climbing for nothing.', 'After crushing the charcoal, you decide to take advantage of your current location and lay out in the sun for a while to get a tan (たん). Instead of getting a tan though, you catch on fire. Oops.', NULL),
  ('00000000-0000-4000-8000-000000001794', 'kanji', '畑', '畑', 41, 23, 'A fire in the rice paddy burns down the field. The rice paddy fire spreads out from the paddy and consumes the field next to it. This rice paddy fire has ravaged your entire farm!', 'Your rice paddy farm and field are on a cay. A cay is a small, sandy island, and since your farm is on fire, this cay has turned into a hot cay. Or as Mario would say, that’s one-a hot-a cay! (はたけ) Mama mia!', NULL),
  ('00000000-0000-4000-8000-000000001795', 'kanji', '包', '包', 41, 24, 'The wrap radical and the wrap kanji are the same!', 'Think about being wrapped up, nice and warm and safe in your home (ほう). Home is where you wrap yourself in a blanket, in the warmth of the fireplace, in the arms of those you love.', NULL),
  ('00000000-0000-4000-8000-000000001796', 'kanji', '衣', '衣', 41, 25, 'The clothes radical and the clothes kanji are exactly the same! Surprising!', 'An eagle (い) sees a pile of your clothes and lays an egg (え) in them. The eagle’s egg needs a soft warm place to incubate, and your pile of clothes is the perfect place.', NULL),
  ('00000000-0000-4000-8000-000000001797', 'kanji', '仁', '仁', 41, 26, 'This leader has two things that remind him of his humanity: his shoes, and his hat. These two things remind the leader of his humanity because humans are the only ones who wear shoes and hats.', 'Another thing that reminds you and the leader about your humanity is wearing jeans (じん). Jeans are the go-to legwear for many people, and no one but humans wear them. Jeans are another great symbol of humanity.', NULL),
  ('00000000-0000-4000-8000-000000001798', 'kanji', '鉱', '鉱', 41, 27, 'Aside from gold there are a wide variety of other minerals as well.', 'One person is trying to control all the minerals of the world. That person is Emperor こういち.', NULL),
  ('00000000-0000-4000-8000-000000001799', 'kanji', '至', '至', 41, 28, 'Dig up a mole and you attain a mole status. You''re always trying to attain a new level for yourself and now you get to be on the mole level!', 'Mole isn''t enough, you want to attain sheep (し) status next. Everyone knows it goes human > mole> sheep. Now you need to stand in the field with the mole and get a sheep to come over.', NULL),
  ('00000000-0000-4000-8000-000000001800', 'kanji', '誠', '誠', 41, 29, 'Something you say to someone you become attached to should be said with sincerity. You need to speak with sincerity when you say things to someone who will eventually become your significant other, for example.', 'When you say something with complete, unabashed sincerity your special saber (せい) starts to pulse with the beating of your heart. It shows the person you want to become close to that you truly are sincere!', NULL),
  ('00000000-0000-4000-8000-000000001801', 'kanji', '郷', '郷', 41, 30, 'Everyone has a poop guy from their hometown. You know. That poop guy. And every single time you try to visit your hometown, poop guy is there making everyone uncomfortable and reminding you why you left in the first place.', 'Your hometown is in きょうと which, unfortunately, means your poop guy is in きょうと too. Now every time you go back home he''s there stinking everything up.', NULL),
  ('00000000-0000-4000-8000-000000001802', 'kanji', '侵', '侵', 41, 31, 'There is a tiny leader on Wolverine’s forehead sitting on a stool and commanding his troops to invade Wolverine’s brain. These tiny soldiers are going to invade Wolverine’s body in an attempt to destroy him. The leader himself isn’t going to invade Wolverine’s brain, he’s just going to sit on the stool and supervise.', 'Soon they realize that they cannot invade Wolverine through his head so they travel down to his leg and try to enter through his shin (しん). The little soldiers take a big knife and slice open Wolverine’s shin in order to invade his body.', NULL),
  ('00000000-0000-4000-8000-000000001803', 'kanji', '偽', '偽', 41, 32, 'The leader gets a nice uniform for the sake of not wanting to look like a fake. The leader is a fake, he just doesn’t want to look like one. He’s not really a leader, but he thinks he should get an official-looking uniform for the sake of not looking like a fake.', 'Well, everyone found out he was a fake anyway, and now you''re all going to use a guillotine (ぎ) to cut off his fake head.', NULL),
  ('00000000-0000-4000-8000-000000001804', 'kanji', '克', '克', 42, 4, 'Even though you’ve old legs, you overcome your disability. These old legs of yours don’t work very well, but you overcome the odds and you run a marathon!', 'When you pass the finish line and finally overcome the limits of your old legs, someone hands you an ice cold Coke (こく) as a reward. Mmm, such a refreshing Coke.', NULL),
  ('00000000-0000-4000-8000-000000001805', 'kanji', '到', '到', 42, 5, 'The mole has a knife ready for your arrival. You get out of your airplane, you step on the ground and... ouch! You stepped right on the knife, and there''s the mole, sticking it out of the ground. "I checked the schedule for your arrival!" it squeaks happily, and disappears.', 'Your arrival to とうきょう is now ruined. And your next stop is now going to be an arrival at a とうきょう hospital to get this mole knife out.', NULL),
  ('00000000-0000-4000-8000-000000001806', 'kanji', '双', '双', 42, 6, 'If you have one stool and another stool, you have a pair of stools. Look at this pair of stools. Look at it.', 'This pair of stools shares a soul (そう). Even if you tried to separate them, they''d eventually find their way back together.', NULL),
  ('00000000-0000-4000-8000-000000001807', 'kanji', '哲', '哲', 42, 7, 'Put an axe in your mouth with your fingers to express your philosophy. Your philosophy of putting weapons in your mouth. Everyone else seems to think it''s a stupid philosophy, so you''re showing them that it''s not with actions!', 'Your philosophy on weapons in mouths means you''re always tasting 鉄 (てつ). They say blood tastes like copper, well weapons taste like iron.', NULL),
  ('00000000-0000-4000-8000-000000001808', 'kanji', '喪', '喪', 42, 8, 'Under the cross is a mouth and another mouth wearing special clothes because they''re in mourning.', 'As the mourning continues, the soul (そう) of the dead person rises out of the cross. The soul looks around at all of the mourners and nods. Yes, your mourning has pleased it.', NULL),
  ('00000000-0000-4000-8000-000000001809', 'kanji', '堅', '堅', 42, 9, 'A servant secures a stool in the dirt so that it is a solid sitting device. If you just throw a stool on the ground it will flop over easily. But if you have a servant to dig it into the dirt a bit, it becomes nice and solid and safe for sitting!', 'You need this stool to be extra solid because you''re using it to test your new catapult (かた). If it isn''t solid, when you launch it and yourself in the catapult, the stool might fall over, killing you both. And you don''t want that, now do you?', NULL),
  ('00000000-0000-4000-8000-000000001810', 'kanji', '床', '床', 42, 10, 'Under the canopy, you use a tree for your floor. It also becomes your bed, because hey, what is a floor but the original bed?', 'News of your amazing floor / bed spreads and reaches the Shougun (しょう), who wants to come see it. He''s impressed, and asks you to build floor beds out of trees laying under this canopy in all of his buildings.', NULL),
  ('00000000-0000-4000-8000-000000001811', 'kanji', '括', '括', 42, 11, 'Someone''s fingers touch your tongue and fasten it together. You can''t talk. All you can do is make sad tongue-less sounds as you try to figure out who would fasten your tongue like this.', 'Only one creature could use its fingers to fasten your tongue like this: cats (かつ). Cats are notorious for fastening tongues so that people can''t speak. Haven''t you ever heard the phrase, "Cat got your tongue?"', NULL),
  ('00000000-0000-4000-8000-000000001812', 'kanji', '弧', '弧', 42, 12, 'Shoot a melon out of a bow and it will fly in a steep arc. Melons are too heavy to fly straight, after all.', 'Shooting melons in an arc is something little 子''s (こ) love to do. It also helps that when they come down from the arc they smash all over the place.', NULL),
  ('00000000-0000-4000-8000-000000001813', 'kanji', '挑', '挑', 42, 13, 'When your fingers move like that, you know it''s an omen of a challenge that will face you soon in the future.', 'In your finger, you see a challenge. And... if you look closely, you can see the fast movements of your fingers forming the outline of Mrs. Chou''s (ちょう) face. Oh no, the challenge is going to be Mrs. Chou!', NULL),
  ('00000000-0000-4000-8000-000000001814', 'kanji', '掘', '掘', 42, 14, 'You see a flag near the exit, so you use your fingers to dig there. Most flags mark something, and this exit is pretty obvious, so there must be something under here. At least that''s what you think to yourself as you dig.', 'You dig until you finally hit something. It''s a bunch of buried old coots (くつ). They''re in an underground room for old coots. One yells up at you, "Whatcha doing to our roof, ya whipper snapper?! Stop digging in our lawn!"', NULL),
  ('00000000-0000-4000-8000-000000001815', 'kanji', '揚', '揚', 42, 15, 'If you have fingers it''s easy to hoist things above your head. If you don''t have fingers, well, it''s not so easy.', 'Today, you have to hoist so much stuff. "Ah!" you say, "So much hoisting to do." Better get to it!', NULL),
  ('00000000-0000-4000-8000-000000001816', 'kanji', '握', '握', 42, 16, 'You use your fingers in a shop to grip what you want to buy.', 'You have a really strong grip thanks to acupuncture (あく)! All your fingers are primed for buying things. You can grip anything at a shop—pineapples, tires, even live turtles. All thanks to some well-placed needles.', NULL),
  ('00000000-0000-4000-8000-000000001817', 'kanji', '揺', '揺', 42, 17, 'You grab a satellite with your fingers and shake it! You''re an astronaut and it''s your job. Don''t worry, the satellite won''t break or anything, it''s strong for space travel. Just do as you''re told and shake the sucker.', 'You need to shake it because this satellite is full of yogurt (よう). And you only like yogurt that''s been well shook. And who can resist space yogurt? Huh? Anyone?', NULL),
  ('00000000-0000-4000-8000-000000001818', 'kanji', '斎', '斎', 42, 18, 'Use simultaneous jackhammers to perform the purification ritual. Two jackhammers running perfectly in sync will purify your body, mind, and soul! (And the ground around you that''s being jackhammered.)', 'This purification ritual is supposed to help you forget your cyborg (さい). It''s been a while, but you can''t seem to get it out of your head.', NULL),
  ('00000000-0000-4000-8000-000000001819', 'kanji', '暫', '暫', 42, 19, 'To your car you take an axe. The sun has broken your car for good this time (you think). You''re so angry at your car. You think this is permanent. Turns out, though, that it''s not permanent. It''s just like that temporarily. You did make it permanent by taking an axe to your car, though.', 'You were driving around in Zanzibar (ざん) when this happened, too, so now you''re stuck in Zanzibar, a foreign place, and you have no idea what to do next.', NULL),
  ('00000000-0000-4000-8000-000000001820', 'kanji', '析', '析', 42, 20, 'You hit a tree with an axe so you can do some analysis on it. To do the analysis on the tree, a cross section needs to be obtained, so you must chop it in half with your axe.', 'The person who is doing this analysis is very sexy (せき). Who is this sexy person? Why it’s you of course, you sexy beast. I love watching you do analysis on trees. It’s so sexy.', NULL),
  ('00000000-0000-4000-8000-000000001821', 'kanji', '枢', '枢', 42, 21, 'In the tree district of town you can buy a lot of tree products, including doors. With those doors, though, you always need hinges.', 'You buy an awesome hinge and try it out. Instead of working properly, it just falls apart and the door falls on you, crushing your lower body. You yell out (and you have to yell) "I''m GOING TO SUUUUEEE (すう) YOU!"', NULL),
  ('00000000-0000-4000-8000-000000001822', 'kanji', '軸', '軸', 42, 22, 'For a car, the reason why it works is because its wheels spin on their axis. That is, they have axles.', 'Your friend''s car doesn''t have axles, but he loves it anyway. He''s all like, "Isn''t this a cool car?" You reply: "Gee, cool" (じく) very sarcastically.', NULL),
  ('00000000-0000-4000-8000-000000001823', 'kanji', '柄', '柄', 42, 23, 'You walk up to a tree and put dynamite on it. Then you set it off. BOOM. It explodes, but doesn''t do what you''d expect. Instead of blowing the tree up, it blasts a very beautiful pattern into the side of it as well as the ground around it.', 'The pattern is so beautiful that you want to put it on your garage (がら). So, you do.', NULL),
  ('00000000-0000-4000-8000-000000001824', 'kanji', '泊', '泊', 42, 24, 'The tsunami that is white is the most scary tsunami of all. It doesn''t come in and destroy everything. No, it comes in, goes inside your door, then stays at your place overnight, without even asking!', 'Your cat walks up to the white tsunami that''s staying overnight and decides it doesn''t like it, so it hacks (はく) up a hairball on it. Even that doesn''t get the tsunami to leave.', NULL),
  ('00000000-0000-4000-8000-000000001825', 'kanji', '滑', '滑', 42, 25, 'A tsunami breaks your bones, not from hitting you, but from making the ground slippery. The water from the tsunami made all the sidewalks and stairs too slippery to walk on, but you tried anyway, slipped, and broke a couple bones.', 'As you struggle on the slippery ground you hear a loud yowling sound. You turn and see a bunch of stray cats (かつ) slipping and sliding too. They''re coming right for you, uh oh!', NULL),
  ('00000000-0000-4000-8000-000000001826', 'kanji', '潟', '潟', 42, 26, 'A tsunami crashes into the sun (breaking it in half) and creating a different wing of the tsunami all together. This wing crashes down and creates a lagoon.', 'This lagoon was created on purpose by a really angry dude and his catapult (かた). He wanted a nice place to lounge that''s tropical, but not too bright. So he came up with a plan: use a giant catapult to send a tsunami into the sun!', NULL),
  ('00000000-0000-4000-8000-000000001827', 'kanji', '焦', '焦', 42, 27, 'You take a turkey and try to boil it but you char it instead. That''s what happens when you throw meat into a pot on high with no water in there.', 'You''re staring sadly at the charred turkey when you suddenly sense the Shougun (しょう) looming behind you. You were supposed to be cooking this turkey for him and now he looks really, really mad.', NULL),
  ('00000000-0000-4000-8000-000000001828', 'kanji', '範', '範', 42, 28, 'This bamboo can be whittled into an example of anything. See, here''s a car. Here''s a snake. I can make so many examples just with bamboo.', 'One last example for you. Now I''m going to take this bamboo and whittle it into an example of Han (はん) Solo!', NULL),
  ('00000000-0000-4000-8000-000000001829', 'kanji', '紛', '紛', 42, 29, 'Take this thread and look at this part. Now look at this part! Now look at this part. You don''t know where to look! Haha, I have distracted you!', 'Despite how distracted you are, that was indeed a lot of fun (ふん).', NULL),
  ('00000000-0000-4000-8000-000000001830', 'kanji', '糾', '糾', 42, 30, 'Thread and vines alone are too weak to hold anything up. You need to twist them together to make them strong.', 'As you twist the thread and vines together, suddenly you feel a lump. You look down and see a cucumber (きゅう) twisted into it.', NULL),
  ('00000000-0000-4000-8000-000000001831', 'kanji', '綱', '綱', 42, 31, 'If you take a thread and wrap up a bunch of it, so much it becomes a hill of thread, you''re going to have a lot of thread. You can wrap some of that thread around other thread to create a much thicker thread. This thread is a cable.', 'You use this cable to swing down from a building but you need to do it soon (つな)! You''re being chased by some bad guys and they''ve almost caught you, so if you''re gonna swing to safety with this cable, you need to do it soon.', NULL),
  ('00000000-0000-4000-8000-000000001832', 'kanji', '網', '網', 42, 32, 'You have a thread hill, but the hill is a bit weird looking (take a look at the hill radical in this kanji). It''s not any normal hill, it''s a weird lumpy hill that isn''t quite right. That''s because it is a thread hill of netting, and parts of the nets have caught things, like fish and cats, so there''s weird abnormal lumps in them.', 'There''s so much netting that it''s out of control. You decide to take your lawn mower to mow (もう) it all down.', NULL),
  ('00000000-0000-4000-8000-000000001833', 'kanji', '肝', '肝', 42, 33, 'If the moon is dry, it''s good for your liver! Haha, get it? Because there''s no moonshine to ruin your liver. Don''t drink, kids.', 'As you pat your liver suddenly a strange feeling bubbles up and the ghost of Genghis Khan (かん) comes out! Right out of your liver.', NULL),
  ('00000000-0000-4000-8000-000000001834', 'kanji', '芝', '芝', 42, 34, 'There are flowers and hills in your front lawn. Your lawn is pretty big and it is covered with both flowers and hills. It’s very pretty.', 'You are the proud owner of a Shiba (しば) Inu, y’know, the Japanese dog? Well, this Shiba Inu of yours loves to run around in your lawn and through the flowers and over the hills. This is the perfect lawn for your Shiba.', NULL),
  ('00000000-0000-4000-8000-000000001835', 'kanji', '荒', '荒', 42, 35, 'Flowers find their death in a river out in the wild. Flowers live on water, but this river drowns the flowers to death. The wild is a dangerous place.', 'Ah (あ), the flowers in the wild have been claimed à la (あら) the great flood. Ah, you don’t think so? Well I do.', NULL),
  ('00000000-0000-4000-8000-000000001836', 'kanji', '袋', '袋', 42, 36, 'You keep your substitute clothes in a sack. The clothes in the sack are just substitute clothes, so they only come out in emergencies.', 'You need your substitute clothes so you take out your substitute clothes sack. You open it up to grab your substitute clothes, only to find out that there is a ton of salmon roe inside your sack. Oh man, you forgot all about putting that in there. You yell: F**K ROE (ふくろ) because that roe destroyed all your clothes and made it nasty.', NULL),
  ('00000000-0000-4000-8000-000000001837', 'kanji', '誰', '誰', 43, 3, 'Who will say turkey? Who? WHO???', 'Then, someone says turkey. "Who said turkey? You? How dare (だれ) you."', NULL),
  ('00000000-0000-4000-8000-000000001838', 'kanji', '珍', '珍', 43, 4, 'The king''s hat, not to mention the hair stuck to said hat, is incredibly rare. If you have your hands on either of these things, you''ll be a rich duck.', 'Then you look closer at the hat. It''s about to get even rarer. Attached to the hair is the king''s chin (ちん).', NULL),
  ('00000000-0000-4000-8000-000000001839', 'kanji', '裂', '裂', 43, 5, 'When a yakuza takes a knife to clothes, it will of course cause a split or tear.', '"I want to split and tear that." You agree, so you say Let''s (れつ) do it.', NULL),
  ('00000000-0000-4000-8000-000000001840', 'kanji', '襲', '襲', 43, 6, 'Imperial clothes allow you to perform an ancient attack that cannot be repelled.', 'The attack''s power is concentrated in the shoes (しゅう) in this imperial outfit. You attack with your feet, kicking the enemy with your old, fancy shoes.', NULL),
  ('00000000-0000-4000-8000-000000001841', 'kanji', '貢', '貢', 43, 7, 'This construction project made from shellfish will act as a tribute to the Crabigator.', 'This great tribute is being commissioned by Emperor こういち.', NULL),
  ('00000000-0000-4000-8000-000000001842', 'kanji', '趣', '趣', 43, 8, 'You have to run, put your ear on the stool, then run back. That''s the charm of this game.', 'The added charm of this game is that there''s this big chute (しゅ) at the end. It''s so charming because you love chutes.', NULL),
  ('00000000-0000-4000-8000-000000001843', 'kanji', '距', '距', 43, 9, 'A foot on a giant is a pretty long distance for a normal person to walk. Giants have big feet and can travel large distances very quickly.', 'Going to Little Kyoto (きょ) is a short distance for a giant but a long distance for you.', NULL),
  ('00000000-0000-4000-8000-000000001844', 'kanji', '籍', '籍', 43, 10, 'People had to ride their bamboo plows long ago to enroll in things. There were no cars yet, so they would hitch a cow to their bamboo plow, and dig their way to the government office or school to enroll.', 'If you enroll in something new people will find you very sexy (せき). This was true long ago too. There''s nothing sexier than trying to improve yourself.', NULL),
  ('00000000-0000-4000-8000-000000001845', 'kanji', '露', '露', 43, 11, 'If the rain touches your foot and gives it a little rain kiss, you know that part of your foot is exposed to the elements. You can also see some dew forming on your exposed foot. So that''s what rain kisses are!', 'You run along the road (ろ), trying to get out of the rain, but the road keeps going and going, with walls on both sides.', NULL),
  ('00000000-0000-4000-8000-000000001846', 'kanji', '牧', '牧', 43, 12, 'A cow in the winter doesn''t like to leave the barn to go to the pasture. It has to, though, because a cow''s gotta eat.', 'ぼく is one of the common ways to say "I" in Japanese (which you should remember!). In this case, you''re a boy... a cowboy, and you say, "ぼく will take these cows out to pasture!"', NULL),
  ('00000000-0000-4000-8000-000000001847', 'kanji', '刷', '刷', 43, 13, 'You take out a flag, lay a towel below it, and use your knife to carve the pattern through them both. Voila! This is exactly how old printing presses used to work.', 'As you''re working on printing your own flag onto this towel you look over and see someone else just sat (さつ) down on theirs. "Excuse me, where is your knife?" you ask. "Oh, this way is slower, but it''s less work. I''m just pressing them together with my bum."', NULL),
  ('00000000-0000-4000-8000-000000001848', 'kanji', '朗', '朗', 43, 14, 'A good moon is a bright moon. Not just in terms of light, but in mood as well. Like, gee wiz, what a bright, happy moon.', 'It''s so bright that you can see all the roe (ろう) in the sea glowing and reflecting the light like stars. And the tiny baby fishies inside the roe are smiling brightly back up at the moon!', NULL),
  ('00000000-0000-4000-8000-000000001849', 'kanji', '潮', '潮', 43, 15, 'A small tsunami comes in the morning with the moon. That just means the ocean gets bigger when the moon''s out, and that my friends is simply the tide.', 'You go check out the tide. The water is coming in a little stronger, and something washes up on the shore. It''s a body! You roll the body over and it is Mrs. Chou (ちょう)!', NULL),
  ('00000000-0000-4000-8000-000000001850', 'kanji', '即', '即', 43, 16, 'The root of a stamp is to get an instant picture down. Back in the olden days, people had to make seals and draw out things by hand, so stamps came about so you can—BAM—just stamp it and have what you want in an instant.', 'Think about the thing you want to make instant. I''d want instant socks (そく)! Don''t waste time searching for a matching pair or pulling them on. Just take out a pair of instant socks, add water, and the socks are already on your feet. In an instant!', NULL),
  ('00000000-0000-4000-8000-000000001851', 'kanji', '垣', '垣', 43, 17, 'Look at the dirt on the ground at dawn and you''ll be able to see all the hedges growing in the area really well. At any other time of day, hedges tend to blend into their surroundings. But at dawn, the shadows the sun makes really helps them stand out.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000001948', 'kanji', '棟', '棟', 46, 9, 'There’s a tree in the east that looks like a pillar. The tree is tall and straight and does not have any leaves or branches. The tree is basically a big wooden pillar that just happens to be alive still.', 'That pillar happens to be in the center of とうきょう. If you need to find east (which is where とうきょう is), you just look for the pillar.', NULL),
  ('00000000-0000-4000-8000-000000001949', 'kanji', '吾', '吾', 46, 10, 'I have five things in my mouth and I need them all for me. I own these five things, and I keep them in my mouth so people like you cannot take them from me.', 'Me, personally, I am quite thirsty so I ask for some “waga” (わが). I have five things in my mouth, so it is hard for me to pronounce the word “water”. So it sounds like “waga” when I ask for it. “Coulg I pweash hab sum waga?! I deed waga!!”', NULL),
  ('00000000-0000-4000-8000-000000001950', 'kanji', '斬', '斬', 46, 11, 'You use your car and an axe to slice down a pedestrian. This innocent guy is just walking along the road when you drive up to him in your car and axe him to death with your axe. You’re all like, VROOM! AXE! Now this guy is dead because you sliced him down in cold blood.', 'You were driving around in Zanzibar (ざん) when you sliced down this man. Luckily, Zanzibar has no laws at all, so you won’t get arrested for slicing down this guy with your axe.', NULL),
  ('00000000-0000-4000-8000-000000001951', 'kanji', '寧', '寧', 46, 12, 'On the roof is your heart. OR! In a net in the street. Which would you rather?', 'As you try to decide which you''d rather have, your neighbors (ねい) come out and grab the heart out of your hands.', NULL),
  ('00000000-0000-4000-8000-000000001952', 'kanji', '椅', '椅', 46, 13, 'This tree is very odd, to say the least. The shape is all crazy, like a lightning bolt stuck into the ground, or something. Oh wait, look at this. I can sit on it really nicely. It''s just like a chair!', 'But, this odd tree chair is also home to an eagle (い). It swoops down upon you as you sit down, gouging your eyes out.', NULL),
  ('00000000-0000-4000-8000-000000001953', 'kanji', '歳', '歳', 46, 14, 'You need to stop a drunkard from going down a slide with a jackhammer to ask him how many years old he is. He''s doing a lot of dangerous things right now, and they all have age limits.', 'When you ask him how many years old he is, he turns to you and screams, "I''M A MILLION YEARS OLD AND YOU''LL NEVER STOP ME!" That''s obviously not how old this kid is, so you take out your holy blue saber (せい) and slice the slide in half. Then the jackhammer. Then the kid''s metal arm—wait! This kid is a cyborg (さい)!', NULL),
  ('00000000-0000-4000-8000-000000001954', 'kanji', '涼', '涼', 46, 15, 'A tsunami causes the capital to become very cool. The capital was already a pretty cool temperature, but with the addition of the water from the tsunami, the capital is now very cool.', 'You don’t like how cool it is in the capital now so you decide to get in your row (りょう) boat and row away to some place that is not so cool. Get in your row boat and row away!', NULL),
  ('00000000-0000-4000-8000-000000001955', 'kanji', '猿', '猿', 46, 16, 'An animal that kicks dirt into people''s mouths is a monkey. Monkeys are naughty little things. You should be happy it was just dirt it kicked into your mouth, and not something worse.', 'You spit the dirt out of your mouth and look back at the monkey to see that it''s saluting (さる) you. Is... is it mocking you?', NULL),
  ('00000000-0000-4000-8000-000000001956', 'kanji', '瞳', '瞳', 46, 17, 'Inside your eye stands a tiny village that makes up your pupil. That''s the black part of your eye!', 'All of the people in your pupil eat doughnuts (どう) all day long. That''s why your eye is shaped like a doughnut, with the "hole" (village) as their home.', NULL),
  ('00000000-0000-4000-8000-000000001957', 'kanji', '鍵', '鍵', 46, 18, 'You take some gold and cover your yoga brush in it, turning it into a key. You shove the brush you normally use for yoga into the lock to your car and pour the gold over it. Now it''s the right shape to be a key!', 'This key has to be perfect, because if it isn''t the car guillotine (かぎ) will come down and chop off your hand!', NULL),
  ('00000000-0000-4000-8000-000000001958', 'kanji', '零', '零', 46, 19, 'You get rain orders. Your orders are to make sure there is zero spill.', 'The best way to make sure there is zero spill when it rains is to get rid of the rain. You use a special ray (れい) gun and zap the rain right out of the sky. There will be zero spills because there will be zero rain.', NULL),
  ('00000000-0000-4000-8000-000000001959', 'kanji', '碁', '碁', 46, 20, 'A crab moves a stone because he is playing the game Go. You know this game, right? You put black or white stones on a board until you win the game. This is the Japanese game known as Go. This crab is pretty good.', 'Go is pronounced Go (ご) in Japanese, too. How convenient is that? Like, super convenient. So easy even a crab could remember!', NULL),
  ('00000000-0000-4000-8000-000000001960', 'kanji', '租', '租', 46, 21, 'Someone with a top hat comes and tells you that your grains are going to be taxed from now on. Top hat man says there is a tariff that''s been enacted on grains. Rice? Triple the price. Wheat? Quadruple.', 'You''re listening to all the things in this tariff and you finally get fed up and ask what isn''t being taxed now. The top hat man looks at you and smiles, holding out his hand. In his hand is some soap (そ).', NULL),
  ('00000000-0000-4000-8000-000000001961', 'kanji', '幽', '幽', 46, 22, 'Poop Poop Mountain is covered in poop because it is such a secluded place.', 'The secluded Poop Poop Mountain is a favorite of youths (ゆう). They go there to get away from their phones to get in touch with nature again.', NULL),
  ('00000000-0000-4000-8000-000000001962', 'kanji', '泡', '泡', 46, 23, 'If a tsunami wraps around itself, the resulting wave will create a lot of bubbles. You know how tsunamis wrap around once gravity kicks in, right? Well when that wave crashes, a whole lot of bubbles are created.', 'One of the biggest bubbles heads straight for your home (ほう), engulfs it, and picks it up into the air!', NULL),
  ('00000000-0000-4000-8000-000000001963', 'kanji', '癖', '癖', 46, 24, 'When you get sick you always eat a hot pepper. It''s a habit you''ve picked up and you can''t seem to shake it. One sniffle, one cough, and before you know it, you''re eating a hot pepper or two.', 'Everyone you know has a different habit when they get sick. Instead, they eat couscous (くせ). But you think couscous is gross. It''s bland and does nothing for your stuffy noses and scratchy throats. I wonder how you can convince them to replace their habit with your own.', NULL),
  ('00000000-0000-4000-8000-000000001964', 'kanji', '鍛', '鍛', 46, 25, 'You want to turn your gold comb into a weapon, so you throw it into the forge.', 'You''re trying to work the forge, but it''s harder than you thought. You end up forging outside all day and get a wicked tan (たん).', NULL),
  ('00000000-0000-4000-8000-000000001965', 'kanji', '錬', '錬', 46, 26, 'The gold from the east needs tempering before it can be sold. The gold from the east is good, it just needs some tempering before it’s entirely presentable. You know, tempering like you’d do in a forge.', 'The smithy where you’re doing the tempering is pretty fancy, but it’s just a rental (れん). You haven’t sold enough gold to own a smithy as nice as this one yet, so for now, you rent one. It is pretty swanky though, even for a rental.', NULL),
  ('00000000-0000-4000-8000-000000001966', 'kanji', '穂', '穂', 46, 27, 'The part of the grain people favor the most is the head of the plant. You don''t eat the stems and leaves of rice or wheat plants, right? You eat the head where the grains are.', 'When you want to harvest the head of the plant you''d like to eat, you need to use a hoe (ほ). Using a hoe, you can dig up the bottom of the plant without injuring the head.', NULL),
  ('00000000-0000-4000-8000-000000001967', 'kanji', '帝', '帝', 46, 28, 'You stand your towel up so everyone can see it. This announces that you are the sovereign ruler of this bathroom.', 'As the sovereign ruler of this bathroom, you must choose a monogram to represent your rule. For this, you choose the symbol of the food that passes through you the most: The mighty tater (てい) tot!', NULL),
  ('00000000-0000-4000-8000-000000001968', 'kanji', '瞬', '瞬', 46, 29, 'Your eye gets kicked with a cleat that came careening toward your forehead when it popped off someone doing a dance, and you blink.', 'You blink and blink and soon (しゅん) there are tears coming out of them too. You try to blink them away but it''s not working. Soon you''re crying and blinking and crying some more.', NULL),
  ('00000000-0000-4000-8000-000000001969', 'kanji', '菊', '菊', 46, 30, 'If you pick certain rice or flowers you''ll be put in prison. The most famous of these is the chrysanthemum. Chrysanthemums are super important in Japan because they''re the symbol of the imperial family. They''re even on the cover of Japanese passports. If you get caught picking a chrysanthemum, you''re going to prison.', 'If you go to prison for chrysanthemum picking, everyone in the prison is going to kick (きく) you nonstop. You broke the chrysanthemum picking law, so kicking is your punishment. And believe me, you don''t want these kicks.', NULL),
  ('00000000-0000-4000-8000-000000001970', 'kanji', '誇', '誇', 46, 31, '"Say ''big,'' ground beggar! Have pride!"', 'After giving some pride to the ground beggar, he looks up at you and tears off his beard and skin. "I am a 子 (こ) again, thanks to you!"', NULL),
  ('00000000-0000-4000-8000-000000001971', 'kanji', '庄', '庄', 46, 32, 'You''re standing under a canopy when you see something strange sticking out of the dirt. You pull it, but it won''t budge. You pull harder and harder until the dirt starts rumbling and a giant manor starts rising out of the ground with you on top!', 'The beautiful manor begins to shake and the shougun bursts out of the front door. "WHO HAS UNEARTHED MY SECRET MANOR?!" he screams.', NULL),
  ('00000000-0000-4000-8000-000000001972', 'kanji', '阻', '阻', 46, 33, 'If you see a building wearing a giant top hat, beware! This building is a fake and it''s trying to thwart all of the plans the people in other buildings have.', 'The building next door is being painted, and the top hat building is jealous. It thwarts the painting plans by dumping soap (そ) out of its windows and onto the painters and the building!', NULL),
  ('00000000-0000-4000-8000-000000001973', 'kanji', '黙', '黙', 46, 34, 'Your village wants to take the village dog and boil it, and you can think of no other response than SHUT UP!', 'The villagers are mad that you told them to shut up, and they start to mock (もく) you. They put their hands on their hips, lean forward, cross their eyes, and yell "SHUT UP!" back.', NULL),
  ('00000000-0000-4000-8000-000000001974', 'kanji', '俵', '俵', 46, 35, 'The leader of your sad life aims a kick at the sack you are holding. This leader is in charge of making your life sad. The next step in the leader making your life suck is attempting to kick your sack out of your hands. Your sack holds all your valuables, so it’s not something you want to have kicked.', 'You manage to get your sack out of the way as you shout “Heyo (ひょう)! Look, you missed! Heyo!” Unfortunately your leader’s friend was standing behind you and he kicks your sack as you move it out of the way. “Heyo!” he shouts, mockingly.', NULL),
  ('00000000-0000-4000-8000-000000001975', 'kanji', '綿', '綿', 46, 36, 'The white thread in your towel comes from cotton. We use cotton to make lots of things, like clothes and bedsheets. But white towels are always made from soft, fluffy cotton.', 'This cotton is made by men (めん).', NULL),
  ('00000000-0000-4000-8000-000000001976', 'kanji', '架', '架', 46, 37, 'With the power of your mouth you command a tree to become a shelf. Most of the time one would have to use their hands and tools to turn a tree into a shelf, but you are capable of turning a tree into a shelf by using the power of your mouth.', 'Once you turn the tree into a shelf you put the shelf in your car (か) and sell it at a local pawn shop. You keep doing this over and over again until you are rich. You command the trees to turn into shelves and then you take the shelves in your car to sell them. Easy money.', NULL),
  ('00000000-0000-4000-8000-000000001977', 'kanji', '砕', '砕', 47, 2, 'Take this stone and throw it at nine crosses to smash them! It''s like old-fashioned bowling, but instead of rolling this stone to knock down the crosses, you want to completely smash them to bits!', 'As you smash these crosses, you think of your cyborg (さい) and how much you want to smash the people who took it away from you. Your cyborg was so good at smashing things too. You could be smashing together, if you didn''t have to sell it.', NULL),
  ('00000000-0000-4000-8000-000000001978', 'kanji', '粘', '粘', 47, 3, 'Your rice fortune is sticky. Rice is sticky. So is your rice fortune. Your fortune of rice is sticky because it is made up entirely of sticky rice.', 'This rice is so sticky that you are able to sculpt nendoroids (ねん) from it. Your rice fortune is worth even more now that you are hand making limited edition nendoroids from it.', NULL),
  ('00000000-0000-4000-8000-000000001979', 'kanji', '粧', '粧', 47, 4, 'Sitting safely under your canopy you take rice and dirt, mix it up, and create unique cosmetics for your face.', 'You need these cosmetics because you have a meeting with the Shougun (しょう) coming up. You want to impress him, and you don''t want anyone to copy your look.', NULL),
  ('00000000-0000-4000-8000-000000001980', 'kanji', '欺', '欺', 47, 5, 'A crab will try to hide what it lacks with deceit. Lying, stealing, faking things—no type of deceit is too much for a crab.', 'Deceit can only take you so far, and soon the crab is caught, tried for its crimes and coverups, and sentenced to death via guillotine (ぎ).', NULL),
  ('00000000-0000-4000-8000-000000001981', 'kanji', '詐', '詐', 47, 6, 'They say the key to telling a lie is to totally believe the lie yourself. They say that if you believe your own lie, others will believe it as well. This is key.', 'The lie you told was about not stealing your buddy’s saw (さ). You actually did steal his saw. He saw you steal his saw, but now you are trying to lie your way out of it. It’s not going well.', NULL),
  ('00000000-0000-4000-8000-000000001982', 'kanji', '霧', '霧', 47, 7, 'It''s raining on your spear that has winter power. When the warm rain hits your cold, winter spear, it creates fog.', 'Through the fog you see the shape of a mythical kirin (きり). You can only see the outline through the fog, but you know it''s there.', NULL),
  ('00000000-0000-4000-8000-000000001983', 'kanji', '柳', '柳', 47, 8, 'A tree that is stamped with one pattern, then stamped with another pattern, over and over, is the willow tree.', 'Ryu (りゅう) from Street Fighter really loves willow trees. Ryu loves them so much that he makes out with them. Ryu is open mouth kissing a willow tree. You are watching this. It is happening.', NULL),
  ('00000000-0000-4000-8000-000000001984', 'kanji', '伊', '伊', 47, 9, 'A leader and Wolverine take a slide to Italy. Wolverine’s leader is Professor X, and they are both sliding down a big slide to Italy. How fun!', 'Before Professor X can get off the slide into Italy, a large eagle (い) swoops down and plucks him right out of his wheelchair. That eagle is very strong. Goodbye, Professor X!', NULL),
  ('00000000-0000-4000-8000-000000001985', 'kanji', '佐', '佐', 47, 10, 'The leader of a narwhal construction crew needs all the help he can get. The narwhals are beginning construction on an underwater city. The leader knows the narwhals are hard construction workers, but they’ll need some help building this city.', 'Then you discover a saw (さ) who would be a great big help. This saw is very strong and would help you and your narwhal construction team out a lot. You should make use of this saw right away.', NULL),
  ('00000000-0000-4000-8000-000000001986', 'kanji', '尺', '尺', 47, 11, 'This shrimp is the exact length of a shaku, or Japanese foot. That’s how they came up with this form of measurement. They measured the length of this shrimp and it was the length of a Japanese foot which they deemed the shaku. It’s equal to 30.3cm, very close to one imperial foot.', 'How is shaku, the Japanese foot, pronounced by Shaq (しゃく) in Japanese? Why Shaq pronounces it shaku. It’s pronounced shaku in both English and Japanese.', NULL),
  ('00000000-0000-4000-8000-000000001987', 'kanji', '哀', '哀', 47, 12, 'With a lid, you hit yourself in the mouth and then kick it like a pathetic loser. You kick the lid, even though it is your fault that you hit yourself in the mouth with it. It’s not the lid’s fault. You don’t need to kick it. You’re being pathetic.', 'You kick the lid one last time and it bounces off the wall and hits you in the eye (あい). How pathetic. You are a pathetic mess. You should have never kicked the lid. Now both your eye and your mouth are in pain, you pathetic fool, you.', NULL),
  ('00000000-0000-4000-8000-000000001988', 'kanji', '唇', '唇', 47, 13, 'A landslide came out of your mouth and created your lips. Before the landslide, you just had a wide open mouth hole.', 'Now you can use your new lips to enjoy a nice, cold Kuchi beer (くちびる). The Kuchi people are Afghan Pashtun nomads. They are lesser known for their amazing beer. And you''ve never been able to get this delicious beer into your mouth, but now that you have lips you can get it all in there.', NULL),
  ('00000000-0000-4000-8000-000000001989', 'kanji', '塀', '塀', 47, 14, 'In the dirt there are flags and horns lined up with a lantern attached to them, making a fence. It''s a little weird looking, but these things are definitely supposed to fence something in.', 'You want to know what this fence is fencing in, so you take a step closer. As the light from the lantern gets brighter you see that the fence is around a ton of hay (へい).', NULL),
  ('00000000-0000-4000-8000-000000001990', 'kanji', '墜', '墜', 47, 15, 'A building falls into the dirt when a pig with horns crashes into it. The building literally crashes to the ground when the horned pig attacks it.', 'You pull the poor pig out of the rubble of the crash. It''s not dead, but it had a nasty bump to the head and now thinks it''s a bird. "TWEET (つい)!" says the pig. "Tweet, tweet, tweet!" Poor confused pig.', NULL),
  ('00000000-0000-4000-8000-000000001991', 'kanji', '如', '如', 47, 16, 'With a woman''s mouth, you have a likeness to me.', 'You have a likeness to Jo-Anne (じょ) when you wear that mouth.', NULL),
  ('00000000-0000-4000-8000-000000001992', 'kanji', '婆', '婆', 47, 17, 'A wave crashes into a woman, transforming her into an old woman! The wave washes away all of the woman’s makeup, revealing her to be an old woman. The makeup she had on made her appear to be a much younger woman, but once the wave washed away her makeup, she was revealed for the old woman she is.', 'In an attempt to distract you from the fact that she is actually an old woman, the old woman starts to baa (ば) and act like a sheep. The old woman goes “Baa! Baa!” and hops around on all fours like a sheep.', NULL),
  ('00000000-0000-4000-8000-000000001993', 'kanji', '崖', '崖', 47, 18, 'There is a mountain on top of a bunch of dirt with a steep cliff. This is a bit redundant, but the mountain and the dirt just make the cliff even bigger and steeper and scarier.', 'As you’re peering over this tall cliff, somebody behind you shouts, “Hey, guy (がい)!” This startles you and you tumble down the cliff. Apparently so did he, because you can hear him saying, "Hey guy! OOF! Are you okay? OOF! Guy? Guy!!!” as you both fall.', NULL),
  ('00000000-0000-4000-8000-000000001994', 'kanji', '帽', '帽', 47, 19, 'You take a towel and wrap it around your head to keep the sun out of your eyes. You''ve invented... the hat!', 'People see you wearing this fancy new hat thing and start asking you to share. You grab all your extra towels, roll them up, and bowl (ぼう) them down the street toward everyone who asks for one.', NULL),
  ('00000000-0000-4000-8000-000000001995', 'kanji', '幣', '幣', 47, 20, 'That penguin over there seems to have a towel stuffed with cash.', 'Your eyes follow the cash, and you watch as the penguin stuffs it, towel and all, into a hay (へい) stack. What a smart penguin, people don''t look for cash in hay, they''re too busy looking for needles.', NULL),
  ('00000000-0000-4000-8000-000000001996', 'kanji', '恨', '恨', 47, 21, 'A soul will only inhabit a root if it''s holding a grudge. Have you ever seen a nice, haunted tree? No! They''re always angry and trying to get someone back for something.', 'If you see one of these grudge trees, it''s probably inhabited by the soul of a condor (こん). Humans tend to kill condors and take their trees away to build houses and make toilet paper. So condors hold pretty bad grudges against us, and so their souls end up stuck in a lot of trees.', NULL),
  ('00000000-0000-4000-8000-000000001997', 'kanji', '憎', '憎', 47, 22, 'The soul mask helps you to see the deepest part of anyone''s soul. You look around and in all the people you only see hate.', 'It turns out you''re not looking at normal people. You see so much hate because all the people you''re looking at are actually just a group of zombies (ぞう).', NULL),
  ('00000000-0000-4000-8000-000000001998', 'kanji', '憩', '憩', 47, 23, 'You keep your tongue to your self to give your heart a rest. You’ve been talking and moving your tongue around all day expressing your feelings. This has tired both your tongue and your heart out, so you stop your tongue moving and decide that you need some self rest time.', 'What better way to rest than to eat some cake (けい)! No talking necessary. Just enjoy the delicious taste of cake on your tongue and feel your heart let out a sigh of relief.', NULL),
  ('00000000-0000-4000-8000-000000001999', 'kanji', '扇', '扇', 47, 24, 'After passing through a door, you use a feather to put the finishing touches on a folding fan. The door leads to your folding fan workshop where you make all your folding fans. This folding fan is now complete that you’ve added a feather to it. How lovely it is.', 'Your biggest folding fan customer is a centaur (せん). This centaur just loves your folding fans and this one you just made with the feather was for the centaur’s latest order. You go back out your door and deliver this folding fan to the centaur.', NULL),
  ('00000000-0000-4000-8000-000000002000', 'kanji', '扉', '扉', 47, 25, 'The door a criminal will get into is the front door. Now hold on, you may be thinking, wouldn''t they go for the back door? No! 99% of home invasions happen when you leave your own front door unlocked!', 'To protect your front door from criminals you plan to fill it with heat (ひ). Oh yeah, we''re gonna Kevin McCallister this.', NULL),
  ('00000000-0000-4000-8000-000000002001', 'kanji', '挿', '挿', 47, 26, 'You have fingers in the thousands and while looking up at the sun you decide you want to insert them in there.', 'You insert one finger, it burns up immediately, and its soul (そう) comes flying out screaming for a moment before it disappears. Hmm. You insert another finger and as it burns up, another little soul comes out screeching, "WHY WOULD YOU INSERT ME IN THERE!" and is gone.', NULL),
  ('00000000-0000-4000-8000-000000002002', 'kanji', '掌', '掌', 47, 27, 'A Viking moves your mouth with his hand to manipulate it. He sticks his hand into your mouth. With the Viking''s hand in your mouth, he can make you look like you’re saying anything he wants.', 'The Viking is manipulating you so that he can manipulate the Shougun (しょう)! You and the Shougun have grown pretty close over the last year or so, and this Viking is going to take advantage!', NULL),
  ('00000000-0000-4000-8000-000000002003', 'kanji', '滴', '滴', 47, 28, 'A tsunami hits your mohawk and it begins to drip. The water from the tsunami continues to drip from your mohawk long after the tsunami has passed. There’s a lot of water in your hair now, so it’s probably going to drip for a while.', 'Luckily, you’re a self-proclaimed techie (てき), so you develop a device to stop the drip drip dripping. This techie device of yours is like a hair dryer helmet. You put it over your mohawk, it does its thing, and your hair is dry! Being a techie sure does have its benefits.', NULL),
  ('00000000-0000-4000-8000-000000002004', 'kanji', '炊', '炊', 47, 29, 'Without a fire, you will lack the ability to cook anything. You really need a fire to cook properly. Having a fire will make sure any cooking endeavors you attempt will not fail.', 'You cook your meal evenly by swinging (すい) it back and forth over the fire. You swing it left, you swing it right. You swing it to, you swing it fro. All this swinging ensures a properly cooked meal.', NULL),
  ('00000000-0000-4000-8000-000000002005', 'kanji', '爽', '爽', 47, 30, 'A big treasure treasure treasure treasure is refreshing! Sorry, I can’t say treasure treasure treasure treasure without saying it four times. See? I did it again. Anyway, this big treasure treasure treasure treasure is really refreshing. It’s been a long time since you found a treasure treasure treasure treasure, so finding this big one is really refreshing.', 'You’d had a sour (さわ) taste in your mouth for not being able to find any treasure treasure treasure treasure for such a long time, but now that you found this big one, the sour taste is totally gone and it’s sooooo refreshing!', NULL),
  ('00000000-0000-4000-8000-000000002006', 'kanji', '畳', '畳', 47, 31, 'In the rice paddy there is a forehead with a top hat. It sits atop an area of tatami mats.', 'Who made this creepy tatami mat altar? It was Jourm (じょう) the increasingly concerning farmhand who lives in your village.', NULL),
  ('00000000-0000-4000-8000-000000002007', 'kanji', '瞭', '瞭', 47, 32, 'Rub charcoal under your eyes if you want to see clearly. Sports players also rub charcoal under their eyes to see nice and clear in the bright sun.', 'You have to have clear vision because you''re about to go out in your row (りょう) boat. The light off the water shines right into your eyes and you need the charcoal to clear that up for you. Otherwise you''ll end up crashing into the shore or going over a waterfall to your death.', NULL),
  ('00000000-0000-4000-8000-000000002008', 'kanji', '箸', '箸', 47, 33, 'You give bamboo to someone and they make them into chopsticks. They are very talented at turning bamboo into bamboo chopsticks. This someone is an expert at their profession.', 'Now use those chopsticks to eat some delicious hash (はし) browns! That''s what chopsticks were made for. That''s what they''re always made for.', NULL),
  ('00000000-0000-4000-8000-000000002009', 'kanji', '胴', '胴', 47, 34, 'The moon is the same as your torso. You must have a really huge torso for it to be the same as the moon.', 'Your torso got so big because of all the doughnuts (どう) you ate. You ate so many doughnuts that your torso got to be the size of the moon and then you floated away into space with your own gravitational pull and everything. Doughnuts are dangerous things.', NULL),
  ('00000000-0000-4000-8000-000000002010', 'kanji', '芯', '芯', 47, 35, 'There are flowers growing around a heart with a wick sticking out of it. The heart is a sacrifice to the old gods and the life energy bleeds from the burning wick to feed the flowers. The wick burns, releasing the power of the heart which spreads into the ground around the heart causing the flowers to grow.', 'Sometimes the wick burning the heart isn’t enough for the flowers to grow properly and they get thirsty for the blood from your shin (しん). So, you slice open your shin with a sacrificial knife and drip your blood over the thirsty demon flowers.', NULL),
  ('00000000-0000-4000-8000-000000002011', 'kanji', '虹', '虹', 47, 36, 'An insect specializing in construction builds a rainbow. Did you ever wonder where rainbows come from? Construction insects build them. Construction insects build rainbows.', 'This rainbow building insect is so needy (にじ). He is needy because he needs everyone to look at his rainbow and praise him for what he’s done. “Look at my rainbow! Look at how good it is and I am! I’m so needy! Needy for praise and recognition!”', NULL),
  ('00000000-0000-4000-8000-000000002012', 'kanji', '帳', '帳', 48, 3, 'Take your towel and make it long. It has to be longer than that! For this will be your notebook, which you will write all your notes in.', 'Inside your long towel notebook you just write the same name over and over again: "Mrs. Chou" (ちょう).', NULL),
  ('00000000-0000-4000-8000-000000002013', 'kanji', '蚊', '蚊', 48, 4, 'The type of insect that ruins your writing is the mosquito. You''re trying to write, when you hear that horrible high-pitched mosquito noise in your ear. You jerk your head and swat and it''s gone. But when you look down, there''s lines all over what you were writing.', 'That mosquito noise sounds like it''s driving a tiny car (か) in your ear. How are you supposed to write with a bug driving around going bzzz bzzz like a revving car?', NULL),
  ('00000000-0000-4000-8000-000000002014', 'kanji', '蛇', '蛇', 48, 5, 'There is an insect on the roof in a spoon. It''s there for the eating, and it''s how you plan to attract a snake to your roof.', 'Why don''t you just bring a snake up to the roof yourself? Because snakes are heavy (へび).', NULL),
  ('00000000-0000-4000-8000-000000002015', 'kanji', '貼', '貼', 48, 6, 'Your shellfish are worth a fortune because you decided to paste your fortune to the shellfish.', 'You''re a little crazy, which is why you decided to use paste to paste your entire fortune to these shellfish, and as you paste each one you yell out, "Ha (は)!" Paste.', NULL),
  ('00000000-0000-4000-8000-000000002016', 'kanji', '辱', '辱', 48, 7, 'The landslide measurement humiliates you. You told everyone you couldn''t come to work, that your house had been destroyed and your car was carried away, but then scientists measured the landslide, and it only went a few feet.', 'Your friends and coworkers humiliate you more by making jokes (じょく). "Uh oh, I heard it might rain later, I hope you don''t drown in the inch of water that''s coming!"', NULL),
  ('00000000-0000-4000-8000-000000002017', 'kanji', '鉢', '鉢', 48, 8, 'Cast a book in gold to make a bowl. Books can be bent into the shape of a bowl, so then all you have to do is pour gold over it to keep it in that shape and ta-da! A bowl has been born!', 'The gold bowl has a hatch (はち) attached to it, which used to be the book''s back cover. That''s fine, you use the hatch as a lid for the bowl!', NULL),
  ('00000000-0000-4000-8000-000000002018', 'kanji', '闇', '闇', 48, 9, 'This gate makes the sound of darkness. The gate looks like darkness, but it’s even more creepy that it sounds like darkness too.', 'You decide to taste the darkness and discover that it is so yummy (やみ)! Who knew that darkness was so yummy? Mmm… this darkness tastes so yummy!', NULL),
  ('00000000-0000-4000-8000-000000002019', 'kanji', '隙', '隙', 48, 10, 'In this building there''s a small sun that''s small. They keep this small, small sun inside of a crevice.', 'They keep the sun in the crevice because this is a place where people ski (すき).', NULL),
  ('00000000-0000-4000-8000-000000002020', 'kanji', '霜', '霜', 48, 11, 'Rain falls off a tree and lands in your eye where it turns to frost. It turns to frost because it’s super cold outside and your body is freezing. The rain that fell off the tree turns to frost as soon as it hits your eye.', 'This whole description is pretty emo. You came up with this whole emo frost idea because you are a shemo (しも). An emo who goes by she pronouns.', NULL),
  ('00000000-0000-4000-8000-000000002021', 'kanji', '飢', '飢', 48, 12, 'You’re so hungry that you eat a table so you won’t starve. If you don’t eat this table, you will most definitely starve, so you eat the table to stay alive.', 'After you finish the table, you still feel like you might starve so you decide to eat every key (き) off your key ring. One by one, you eat each and every key so you don’t starve.', NULL),
  ('00000000-0000-4000-8000-000000002022', 'kanji', '餓', '餓', 48, 13, 'If you have nothing to eat but your ego, you''ll starve. You can''t eat it, and your ego is keeping you from accepting actual food or help from other people.', 'You starve (thanks ego) and turn into a gargoyle (が). As your stomach aches, your skin turns gray and you slowly harden into a crouched position.', NULL),
  ('00000000-0000-4000-8000-000000002023', 'kanji', '畜', '畜', 48, 14, 'In the mysterious rice paddy there is some livestock. This livestock is also mysterious because no one knows where it came from. The mysterious livestock are only seen in the mysterious rice paddy. How mysterious indeed.', 'Your favorite member of the mysterious livestock crew is a little chick (ちく). The chick is very cute and little. The chick is also very mysterious because it floats about without even flapping its little wings.', NULL),
  ('00000000-0000-4000-8000-000000002024', 'kanji', '迅', '迅', 48, 15, 'You drive your scooter off this cliff, holding your cross tight to your chest, at a swift speed.', 'Because you had such a swift take off, you didn''t notice that your jeans (じん) were ripped right off your body. Until now.', NULL),
  ('00000000-0000-4000-8000-000000002025', 'kanji', '騎', '騎', 48, 16, 'An odd horse is still a horse. It may look a little funny, but that doesn''t change what it is on the inside.', 'This horse is particularly odd because it knows how to use a key (き). It carries a key around its neck and uses it to get in and out of its stable.', NULL),
  ('00000000-0000-4000-8000-000000002026', 'kanji', '蓄', '蓄', 48, 17, 'Flowers are mysteriously appearing in the rice paddy. No matter what you do to them, they continue to amass.', 'As the flowers amass it starts attracting wildlife. Soon thousands of baby chicks (ちく) are amassing in the rice paddy as well.', NULL),
  ('00000000-0000-4000-8000-000000002027', 'kanji', '尽', '尽', 48, 18, 'You see shrimp on ice at the market in the morning. "I''ll get some on the way home" you think to yourself. Later that evening, you see no shrimp, just ice. The supply of shrimp has been exhausted. It''s all gone! You never thought they''d use up their shrimp supply so quickly.', 'How could the store use up its shrimp supply so quickly? Suddenly you notice the worker behind the fish counter has shrimp stuffed into their jeans (じん) . Aha! The culprit!', NULL),
  ('00000000-0000-4000-8000-000000002028', 'kanji', '彩', '彩', 48, 19, 'You use a cleat to climb a tree and your hair gets the same coloring as the foliage because your hair is like a chameleon. The coloring of your hair changes to whatever color is around you, so you use your cleats to climb trees to make your hair turn green and brown, and in the fall, yellow and orange and red!', 'This cool coloring can only happen because you turned yourself into a cyborg (さい). Your hair and scalp are now made of high tech parts, not human ones.', NULL),
  ('00000000-0000-4000-8000-000000002029', 'kanji', '憶', '憶', 48, 20, 'When your soul has an idea it''s just a recollection of something you already know. Only your brain can have original ideas, so when your soul tries to come up with one, it''s just a recollection of something you thought before now.', 'Your soul is sending you a recollection right now of... your past life as a farmer in Oklahoma (おく). You see yourself farming and sweating and living a wonderful life. Hmm, maybe you should move to Oklahoma and live the simple life again.', NULL),
  ('00000000-0000-4000-8000-000000002030', 'kanji', '溶', '溶', 48, 21, 'The tsunami hits your form and you begin to melt. You are a witch and water makes you melt. The tsunami is a lot of water, so once it touches your form, you begin to melt.', 'The only way to reverse the melt process is to eat some yogurt (よう). The yogurt counteracts the melting from the water and your form will become whole again. Quick, eat some yogurt!', NULL),
  ('00000000-0000-4000-8000-000000002031', 'kanji', '耐', '耐', 48, 22, 'You take a rake in for a measurement but it is resistant. The rake doesn’t want to have its measurements taken. The rake is resistant to have any measurement taken because it feels inferior to the other rakes and doesn’t want to be embarrassed if it ends up being smaller than the others.', 'Because the rake is persistently resistant, you eventually tie it to the table with your neck tie (たい). The tie won’t hold for long, so you need to take each measurement quickly.', NULL),
  ('00000000-0000-4000-8000-000000002032', 'kanji', '踊', '踊', 48, 23, 'Your foot, as your mama says, was given the task to dance. Shake those two foots your mama gave you and dance dance dance!', 'You both dance so much that you develop an odor (おど). Not just any odor, an odor particular to stinky dancing feet.', NULL),
  ('00000000-0000-4000-8000-000000002033', 'kanji', '賢', '賢', 48, 24, 'Your servant uses a stool to break open shellfish. You know how much work shucking shellfish is so this method is really clever.', '"More clever than you!" your servant yells, tearing off his wig. "It is I, Ken (けん) the samurai. I saw you take this shellfish from my master''s lands."', NULL),
  ('00000000-0000-4000-8000-000000002034', 'kanji', '輝', '輝', 48, 25, 'The sunlight shines on your forehead in your car with a great radiance. The car you are in is a convertible, so the sunlight shines right onto your big bald forehead. The sun has a pretty powerful radiance as it is, but the sheen from the sunlight hitting your forehead is the most powerful radiance ever witnessed by man.', 'This radiance is the key (き) to powering your car. Your car runs on reflected solar energy, and the radiance coming from your forehead is the most powerful source of radiant sunlight ever imagined. Your forehead is a perfect key for this car.', NULL),
  ('00000000-0000-4000-8000-000000002035', 'kanji', '脅', '脅', 48, 26, 'There''s power, power, and power stacked on top of the moon, threatening to bring it down!', 'This extra power-filled moon is now trying to threaten the safety of きょうと. All of きょうと is shaking and getting dark as the moon comes closer and closer.', NULL),
  ('00000000-0000-4000-8000-000000002036', 'kanji', '麻', '麻', 48, 27, 'This canopy of trees isn''t actually a canopy of trees at all. When you look closely, you see these trees are actually giant stalks of hemp.', 'Who planted all this hemp? Your mama (ま) did.', NULL),
  ('00000000-0000-4000-8000-000000002037', 'kanji', '灯', '灯', 48, 28, 'Fire you use to light up the street needs to go in a lamp. Campfires, matches? No, none of those work. You need bright, safe lamps to keep the street nice at night.', 'These street lamps were first used in とうきょう. It was the most advanced city after all. And more people were out at night in とうきょう than anywhere else in Japan. So they needed lamps to light things up!', NULL),
  ('00000000-0000-4000-8000-000000002038', 'kanji', '咲', '咲', 48, 29, 'Having a foul mouth and horns will prevent you from getting into Heaven where you would blossom into an angel. If you have horns, you are not meant for Heaven and will not blossom there. To blossom in Heaven, you must not have horns or a foul mouth.', 'You don’t want to blossom into a demon so you saw (さ) off your horns with a saw. If you saw off your horns, maybe you can beg for forgiveness and have your foul mouth forgiven.', NULL),
  ('00000000-0000-4000-8000-000000002039', 'kanji', '培', '培', 48, 30, 'You need to put a clown in the dirt if you want to cultivate good crops there. Clowns act as a natural fertilizer, and this will make it super easy to cultivate any crops you could ever want in this dirt. Isn''t nature amazing?', 'Before you can start this whole cultivation process however, you have to say bye (ばい) to the clown. Say bye to him, then bash his head in, and drop him in the dirt.', NULL),
  ('00000000-0000-4000-8000-000000002040', 'kanji', '悔', '悔', 48, 31, 'If you try to put your soul into everything, you''ll regret it. It''s not so much that putting your soul into things is bad, but every single thing? You''ll burn out immediately. You won''t be able to be good at any of those things. And you''ll regret all the time you wasted trying to be the best at everything.', 'The regret is too strong for you to ignore, so you decide to drop everything but kayaking (かい). If there''s one thing you refuse to regret, it''s your bright orange kayak and all the friends you made at kayaking club.', NULL),
  ('00000000-0000-4000-8000-000000002041', 'kanji', '脇', '脇', 48, 32, 'The moon has a lot of power that is power it gets from the power of every armpit of every human on earth! Why does your armpit smell? It’s because the moon is draining the power from your armpit. The moon saps power from your armpit and that power is sucked up into the sky where the moon collects the power for its own devices.', 'This is a pretty wacky (わき) armpit image isn’t it? Seeing lines of power traveling from your armpit to the moon. Definitely wacky. Have you ever seen something this wacky in real life?', NULL),
  ('00000000-0000-4000-8000-000000002042', 'kanji', '遂', '遂', 48, 33, 'A scooter with horns with a pig riding on it will be able to accomplish anything.', 'It was even able to successfully accomplish a feat that involved it jumping its scooter right into a swing (すい), swinging back and forth, then jumping off.', NULL),
  ('00000000-0000-4000-8000-000000002043', 'kanji', '班', '班', 48, 34, 'If the king gives you a knife you become part of his squad. Every king has a knife squad or two protecting him and making sure his subjects keep in line.', 'This squad is led by Han (はん) Solo, so it''s basically a 50/50 shot that the king is gonna die.', NULL),
  ('00000000-0000-4000-8000-000000002044', 'kanji', '塗', '塗', 48, 35, 'A tsunami surplus will cover all the dirt with paint. The surplus of tsunamis will strike the paint factories first (everyone knows paint factories are built close to the ocean). Then the paint will flow over all the dirt and paint it a ton of rainbow colors.', 'You touch the paint in the dirt with your toe (と) to see if it''s still wet. It is. The paint is still very wet and now your toe looks like a tiny rainbow.', NULL),
  ('00000000-0000-4000-8000-000000002045', 'kanji', '斜', '斜', 48, 36, 'You have a surplus of ladles laid out diagonally in front of you. Why are they diagonal? And why do you have so many ladles? Why the surplus? Hang on, we''ll get there.', 'In front of this diagonal pattern is a shaman (しゃ) who is currently staring at you. You slowly reach down and turn one of the ladles around, diagonally, and look back up. The shaman''s eyes are wide, and now they''re scribbling on in a notebook.', NULL),
  ('00000000-0000-4000-8000-000000002046', 'kanji', '殴', '殴', 48, 37, 'Give a district weapons and it will assault other districts.', 'This assault is all the 王''s (おう) fault. The 王 gave the weapons to each of the districts on purpose so this would happen.', NULL),
  ('00000000-0000-4000-8000-000000002047', 'kanji', '盾', '盾', 48, 38, 'On a cliff, the pope is holding a shield. The pope is near the edge of the cliff and is using the shield to fend off demons. The demons want to shove the pope off the cliff, but the pope is using his holy shield of popery to fend them off.', 'The light of the pope''s shield begins to fade. The shield''s holy power is waning! Just as the demons are about to push him off the cliff, the sun begins to rise. That''s right! It''s June (じゅん) and summer has just begun. The pope''s shield reflects the power of June''s bright sun into the eyes of the demons, casting them off the cliff behind him and back into hell!', NULL),
  ('00000000-0000-4000-8000-000000002048', 'kanji', '穫', '穫', 48, 39, 'You need to feed this grain to a flower wearing turkey on a stool so you start the harvest. Grains don''t pick themselves, you have to harvest them.', 'You''re just starting to harvest the grains when an angry cock (かく) shows up! He''s mad because these are his grains and you''re about to harvest them and feed them to a turkey instead of him.', NULL),
  ('00000000-0000-4000-8000-000000002049', 'kanji', '巾', '巾', 47, 37, 'The kanji and the radical are the same, so remembering the meaning of this kanji is as simple as making sure you know the radical for towel first! If you know the radical, you know this kanji means towel as well.', 'You know who loves towels? The King (きん) of England. He loves towels so much that he went around and put きん on every towel in the land, so you think of him whenever you use one.', NULL),
  ('00000000-0000-4000-8000-000000002050', 'kanji', '駒', '駒', 49, 3, 'The horse who can write a paragraph gets to be a chess piece. Only the most erudite of horses gets selected to be a chess piece. The knight’s chess piece is represented by a horse, and for a horse to earn this honor, they must first write a paragraph explaining why they deserve the honor.', 'Upon being told that he will never be a chess piece, the horse slips into a coma (こま). The horse will never awaken from this coma as he knows he will never fulfill his dream of becoming a chess piece, so he has nothing to live for.', NULL),
  ('00000000-0000-4000-8000-000000002051', 'kanji', '紫', '紫', 49, 4, 'You stop a spoon from moving by tying it with thread that''s purple. The spoon wouldn''t stop moving around, so you had to use your favorite purple thread to make it stop. It''s the strongest thread you have.', 'You have to use all of your purple thread, and now you need more. You go into the back yard and call over your purple sheep (し).', NULL),
  ('00000000-0000-4000-8000-000000002052', 'kanji', '抽', '抽', 49, 5, 'Your fingers give you a good reason to pluck things. You pluck flowers out of the ground. You pluck a cat out of a tree. Why? Because you have fingers! That''s your reason.', 'Now that you have a reason to pluck things (you have fingers, after all) you decide you want to pluck all the fur off of Chewbacca (ちゅう). He is very furry, and you want to know what he looks like under there.', NULL),
  ('00000000-0000-4000-8000-000000002053', 'kanji', '誓', '誓', 49, 6, 'With your fingers under an axe, you say a vow. A vow is a sacred promise, so you have to be really serious when you say one. That''s why you do it with an axe hovering above your fingers—it''s a reminder that if you break this vow your fingers are gonna get chopped off.', 'When you finish your vow, you take out your holy blue saber (せい) and cut the axe in half! You know you''re never going to break your vow, and if you do, you''ll use your own saber to cut off your fingers.', NULL),
  ('00000000-0000-4000-8000-000000002054', 'kanji', '悟', '悟', 49, 7, 'Your soul connects to five different mouths, enhancing your comprehension. You can easily comprehend what each of those souls belonging to those mouths wants and feels deep down.', 'Your comprehension is the strongest with the fifth mouth, belonging to Godzilla (ご). You finally get why he wants to destroy buildings and cities.', NULL),
  ('00000000-0000-4000-8000-000000002055', 'kanji', '拓', '拓', 49, 8, 'You use your fingers and a stone to begin cultivation of the land. You use your fingers to till the soil, the stone to flatten the ground, and you carefully poke the seeds into the dirt and then use the stone to smash them further down.', 'Cultivation is suddenly halted because a tack (たく) sticks into your finger. You pull the tack out, throw it away and start cultivation again when... ouch! There''s another tack. This field is full of tacks!', NULL),
  ('00000000-0000-4000-8000-000000002056', 'kanji', '拘', '拘', 49, 9, 'You run your fingers along the words of a  paragraph. You are learning about the law because you plan to arrest somebody.', 'Who do you want to arrest? You want to arrest こういち. Even though he''s started wars, created a religion, and trapped a child in a cavity, it''s going to be tricky to arrest him because he''s the emperor now.', NULL),
  ('00000000-0000-4000-8000-000000002057', 'kanji', '礎', '礎', 49, 10, 'There’s a stone, a tree, another tree, and a coat rack. That stone and two trees will make the perfect foundation, or cornerstone, for a house to put that coat rack in! This stone is flat and heavy and both of the trees are flexible and durable.', 'After you finish the foundation, the only step that''s left is to wash the entire thing with soap (そ).', NULL),
  ('00000000-0000-4000-8000-000000002058', 'kanji', '鶴', '鶴', 49, 11, 'On the roof there''s some type of turkey bird, but thinner and longer. You look closer and realize it''s a crane.', 'The crane leans down toward you from its roof perch and squawks, "Too rude (つる)!" You''re shocked! You didn''t know the crane could speak English, but even worse, it knew you called it a turkey bird.', NULL),
  ('00000000-0000-4000-8000-000000002059', 'kanji', '刈', '刈', 49, 12, 'Take your greatest treasure, hold a knife nice and close to it, and prune away all the weak and dead bits.', 'Currently, you want to prune your greatest treasure: your car (か). Your car is made of wood, and it keeps trying to grow new buds and branches, so you have to prune them off.', NULL),
  ('00000000-0000-4000-8000-000000002060', 'kanji', '剛', '剛', 49, 13, 'A hill knife is the most sturdy knife you can find.', 'This sturdy (but strangely shaped) knife is used by Grandpa ごういち.', NULL),
  ('00000000-0000-4000-8000-000000002061', 'kanji', '唯', '唯', 49, 14, 'The mouth of that turkey is solely his. It’s very unique, so that mouth could belong to no other turkey but him. That mouth is solely his.', 'You traveled a long way to see this turkey and the mouth that is solely his but you missed your exit on the highway and you have to hang a U-ey (ゆい). You know what hang a U-ey means, right? It’s making a U-turn. Well, you have to hang a U-ey on the highway so you can get off at the right spot to see this turkey and the mouth that is solely his.', NULL),
  ('00000000-0000-4000-8000-000000002062', 'kanji', '壇', '壇', 49, 15, 'On the dirt there is a lid trying to cover the number of times the dawn has risen here. You walk over and pull the lid off and the whole thing transforms into a podium. A podium for the dawn to tell you how many times it''s risen over this dirt over and over again. It just keeps going and you realize the lid was here because this dang podium can''t seem to keep a lid on it! (Get it? Figure of speech!)', 'You listen to what the podium has to say for so long you finally can''t help but ask, "Who are you?" "I''m the dawn (だん), of course!" And this is my podium where I spread the good news about the dawn!', NULL),
  ('00000000-0000-4000-8000-000000002063', 'kanji', '尼', '尼', 49, 16, 'You give a flag and a spoon to a nun as an offering. You give her this flag and this spoon because they are very precious to you and you want to show the nun how serious you are about repenting for your evil deeds.', 'You’re getting down on one knee (に) as you present the flag and the spoon to the nun. The nun accepts your offer and takes your flag and spoon from you. Your soul is saved!', NULL),
  ('00000000-0000-4000-8000-000000002064', 'kanji', '概', '概', 49, 17, 'Bite a tree''s root with your fang to get an approximation on its age. It won''t be exact, this isn''t scientific or anything, but it will be pretty close.', 'As you''re recording your approximation down,  somebody comes up and shouts, “Hey guy (がい)! I’ll give you $10,000 for that tree there, guy!” This guy must be crazy. That’s much more than your approximation of the value of this thing. But you sell it to the guy anyway.', NULL),
  ('00000000-0000-4000-8000-000000002065', 'kanji', '浸', '浸', 49, 18, 'In the event of a tsunami, Wolverine, your forehead, and a stool will all be immersed in it. You will become immersed in the tsunami after it hits because tsunamis are gigantic and bring a lot of water. Now you and your forehead are immersed in the tsunami along with Wolverine and a stool.', 'Still immersed, the stool floats over and hits you in the shin (しん). The tsunami gave the stool a good push and while it was fully immersed, it ran into your shin. It really hurts.', NULL),
  ('00000000-0000-4000-8000-000000002066', 'kanji', '淡', '淡', 49, 19, 'A tsunami and a couple fires run into each other. They cancel each other out completely, and the remainder left behind is a faint remnant of what was once there.', 'Just like the tsunami and fire canceling each other out, leaving a faint remainder of what was, your tan (たん) is extremely faint as well.', NULL),
  ('00000000-0000-4000-8000-000000002067', 'kanji', '煮', '煮', 49, 20, 'If someone wants to boil, you let them boil!', 'Welp, the pot is at a rolling boil and your knee (に) is in there. The person wasn''t saying they wanted to boil, they said they wanted to boil someone. And that meant you. Well, your knee anyway.', NULL),
  ('00000000-0000-4000-8000-000000002068', 'kanji', '覆', '覆', 49, 21, 'If a helicopter loiters near a black hole then it''s going to capsize. I mean, yeah, it''s not a boat, but just look, that''s what''s happening! That helicopter is going down!
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000006481', 'vocabulary', '早瀬', '早瀬', 41, 63, 'Jeram yang cepat akan mempunyai arus yang deras.', 'The reading comes from 早い and the reading you learned for 瀬.', NULL),
  ('00000000-0000-4000-8000-000000006482', 'vocabulary', '瀬', '瀬', 41, 64, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'The reading is the same as the one you learned with the kanji, actually!', NULL),
  ('00000000-0000-4000-8000-000000006483', 'vocabulary', '撤去', '撤去', 41, 65, 'Penarikan adalah sesuatu yang Anda lakukan untuk menghapus sesuatu dari masa lalu. Ini adalah penarikan atau penghapusan apa yang Anda lakukan atau serahkan sebelumnya.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Look out for the shortened てつ.', NULL),
  ('00000000-0000-4000-8000-000000006484', 'vocabulary', '撤回', '撤回', 41, 66, 'Jika Anda melakukan penarikan terhadap sesuatu, rasanya seperti Anda kembali ke keadaan semula. Ini adalah penarikan atau pencabutan. Itu menarik kembali sesuatu yang Anda katakan sebelumnya.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Look out for the shortened てつ.', NULL),
  ('00000000-0000-4000-8000-000000006485', 'vocabulary', '撤兵', '撤兵', 41, 67, 'Penarikan tentara adalah penarikan pasukan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Look out for the shortened てっ spot.', NULL),
  ('00000000-0000-4000-8000-000000006486', 'vocabulary', '措置', '措置', 41, 68, 'Sisihkan dan letakkan apa yang Anda perlukan untuk menyelesaikan pekerjaan di sana. Ini adalah langkah-langkah dan langkah-langkah yang kami ambil untuk memastikan segala sesuatunya dilakukan dengan benar.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006487', 'vocabulary', '措辞', '措辞', 41, 69, 'Anda menyisihkan kata-kata ini secara khusus sehingga Anda dapat menyusun kata-katanya dengan benar. Kata-kata terkadang penting, seperti saat Anda mencoba membicarakan sesuatu yang sensitif, atau saat Anda sedang menulis puisi. Terkadang hanya kata-kata tertentu yang bisa digunakan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006488', 'vocabulary', '拠る', '拠る', 41, 70, 'Kanji artinya berdasarkan dan kata kerja artinya karena. Hal ini mungkin terjadi karena ketika sesuatu didasarkan pada sesuatu, ia melakukan sesuatu yang lain, yang disebabkan oleh hal tersebut. Hal ini disebabkan oleh apa yang mendasarinya.', 'For example, yogurt is due to milk. If milk didn''t exist, neither would yogurt.', NULL),
  ('00000000-0000-4000-8000-000000006489', 'vocabulary', '拠点', '拠点', 41, 71, 'Sesuatu yang berdasarkan poin memiliki peringkat, artinya Anda akan mengetahui di mana posisi atau lokasi Anda, dibandingkan dengan orang lain.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006490', 'vocabulary', '証拠', '証拠', 41, 72, 'Buktinya didasarkan pada sesuatu. Berdasarkan apa? Bukti fisik ini. Ha ha! Bersalah!', 'This is a jukugo word that uses the on''yomi readings of the kanji. You just need to remember that 拠 is using the こ reading you learned, not the きょ one. Just remember that you can never trust the word of a 子 (こ), so you always require them to provide physical evidence.', NULL),
  ('00000000-0000-4000-8000-000000006491', 'vocabulary', '根拠', '根拠', 41, 73, 'Akar yang mendasari hal ini adalah dasar dan dasar argumen saya. Lihat, semuanya sampai ke akar masalahnya!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006492', 'vocabulary', '礼儀', '礼儀', 41, 74, 'Upacara syukur adalah tarian yang Anda lakukan dalam hidup sehubungan dengan sopan santun dan sopan santun Anda kepada orang lain. Juga berarti etiket.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006493', 'vocabulary', '儀式', '儀式', 41, 75, 'Upacara upacara adalah upacara.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006494', 'vocabulary', '祝儀', '祝儀', 41, 76, 'Upacara perayaan adalah sebuah perayaan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You just need to remember that 祝 is read as しゅう for this one and you''ll be fine.', NULL),
  ('00000000-0000-4000-8000-000000006495', 'vocabulary', '辞儀する', '辞儀する', 41, 77, 'Upacara berhenti adalah saat Anda berhenti dan siap untuk pergi ke suatu tempat, maka Anda membungkuk lalu berangkat. Itu sebabnya kata kerjanya adalah membungkuk.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006496', 'vocabulary', '果樹', '果樹', 41, 78, 'Kayu buah adalah tempat tumbuhnya buah (kayu dari buah adalah pohon, bodoh). Itu menjadikan kata ini pohon buah-buahan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006497', 'vocabulary', '樹皮', '樹皮', 41, 79, 'Kulit kayu adalah kulit pohon. Itu adalah kulit kayu di sekitar pohon.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006498', 'vocabulary', '植樹', '植樹', 41, 80, 'Jika Anda menanam kayu, Anda sedang melakukan penanaman pohon, karena hanya pohon yang terbuat dari kayu.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006499', 'vocabulary', '放棄', '放棄', 41, 81, 'Saya melepaskan dan meninggalkan posting saya. Ini adalah pengunduran diri saya. Ini adalah pengabaian saya.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006500', 'vocabulary', '廃棄', '廃棄', 41, 82, 'Itu sudah usang jadi saya akan meninggalkannya. Ini adalah pembatalan. Anda mengirimkan sesuatu untuk dibuang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006501', 'vocabulary', '投棄', '投棄', 41, 83, 'Sesuatu yang Anda buang dan tinggalkan telah dikirim ke alam pengabaian.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You learned the on''yomi for 投 when you learned 投資 a long time ago.', NULL),
  ('00000000-0000-4000-8000-000000006502', 'vocabulary', '虎', '虎', 41, 84, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Bacaannya sama dengan yang Anda pelajari dengan kanji.', NULL),
  ('00000000-0000-4000-8000-000000006503', 'vocabulary', '蛍', '蛍', 41, 85, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'The reading is the one you learned with the kanji.', NULL),
  ('00000000-0000-4000-8000-000000006504', 'vocabulary', '蜂', '蜂', 41, 86, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Bacaannya sama dengan yang Anda pelajari dengan kanji.', NULL),
  ('00000000-0000-4000-8000-000000006505', 'vocabulary', '蜂蜜', '蜂蜜', 41, 87, 'A bee''s honey is its honey, honey.', 'The readings are the ones you learned with the kanji.', NULL),
  ('00000000-0000-4000-8000-000000006506', 'vocabulary', '焼酎', '焼酎', 41, 88, 'Cooked sake is slightly higher in alcohol content. This is shochu, which I''m guessing gets cooked in some way during its production.', 'The reading for 焼 and 酎 are the on''yomi readings, but you didn''t learn the reading for 焼 yet. That''s okay, because if you know the (also English) word Shochu, you''ll be able to remember the reading for this one as well too.', NULL),
  ('00000000-0000-4000-8000-000000006507', 'vocabulary', '蜜', '蜜', 41, 89, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'The reading is the same as the one you learned with the kanji. That''s honey, baby!', NULL),
  ('00000000-0000-4000-8000-000000006508', 'vocabulary', '廃墟', '廃墟', 41, 90, 'Obsolete ruins are places that are abandoned because nobody can run them anymore (due to being obsolete, or due to not having money, or due to whatever else). These things are ruins or abandoned buildings. People like to explore these, a lot.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006509', 'vocabulary', '艦船', '艦船', 41, 91, 'Kapal perang adalah kapal perang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006510', 'vocabulary', '艦隊', '艦隊', 41, 92, 'Pasukan kapal perang adalah armada angkatan laut atau armada.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006511', 'vocabulary', '軍艦', '軍艦', 41, 93, 'Kapal perang tentara adalah kapal perang. Apakah kamu menenggelamkannya? Oh oh! Anda menenggelamkan 軍艦 saya!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006512', 'vocabulary', '潜水艦', '潜水艦', 41, 94, 'Kapal perang yang tersembunyi di dalam air adalah kapal selam.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006513', 'vocabulary', '航空母艦', '航空母艦', 41, 95, 'Kapal perang induk penerbangan (航空) adalah kapal perang yang ibarat ibu bagi semua benda penerbangan (pesawat terbang). Mereka pulang ke kapal induknya, yaitu kapal induk.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006514', 'vocabulary', '潜む', '潜む', 41, 96, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji itu sendiri berarti menyembunyikan, jadi jika Anda menyembunyikan diri dan berjalan-jalan, Anda akan mengintai atau tertidur.', 'He so (ひそ) hidden. Where you at?', NULL),
  ('00000000-0000-4000-8000-000000006515', 'vocabulary', '原潜', '原潜-6515', 41, 97, 'Mesin penyembunyi yang asli (sering dikaitkan dengan atom dan teknologi nuklir) adalah kapal selam nuklir. Itu adalah nuklir, dan ia menyembunyikan dirinya sendiri.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006516', 'vocabulary', '潜水', '潜水', 41, 98, 'Untuk menyembunyikan diri Anda di dalam air, sebaiknya Anda mulai menyelam dan masuk ke dalam air di tempat yang dapat menyembunyikan Anda!', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006517', 'vocabulary', '潜在意識', '潜在意識', 41, 99, 'Jika 意識 adalah secara sadar, maka apa yang tersembunyi dalam pikiran Anda adalah alam bawah sadar Anda.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006518', 'vocabulary', '拳', '拳', 41, 100, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it probably uses the kun''yomi reading. You did not learn this reading, so here''s a mnemonic to help you to remember: You make a fist. Why? Because she stole your corn on the cob. "Cob! She (こぶし) stole my cob!"', NULL),
  ('00000000-0000-4000-8000-000000006519', 'vocabulary', '拳骨', '拳骨', 41, 101, 'Tinju yang seperti tulang (keras) adalah tinju yang terkepal dan siap untuk ditinju, menjadikannya tinju atau ruas jari yang terkepal, jika Anda ingin membuatnya lebih bertulang.', 'This is a jukugo word that uses the on''yomi readings of the kanji. But 拳 doesn''t use the one you learned, it uses げん instead. Just imagine someone clenching their fist at you. You gulp and say げん instead of けん out of fear.', NULL),
  ('00000000-0000-4000-8000-000000006520', 'vocabulary', '炭', '炭', 41, 102, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'I''m gonna put charcoal in your mouth. Whatchoo gonna do? Sue me (すみ)?', NULL),
  ('00000000-0000-4000-8000-000000006521', 'vocabulary', '炭素', '炭素', 41, 103, 'Benda-benda yang mengandung unsur arang terdiri dari banyak karbon. Lihat saja jauh ke dalam arang untuk melihat semua karbon di sana.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006522', 'vocabulary', '石炭', '石炭', 41, 104, 'Arang batu adalah arang yang berbentuk seperti batu kecil. Atau mungkin sering ditemukan di batu. Itu batu bara.', 'This uses the on''yomi for both kanji, so you should be able to read this on your own.', NULL),
  ('00000000-0000-4000-8000-000000006523', 'vocabulary', '〜畑', '〜畑', 41, 105, 'The kanji and the word are exactly the same. That means they share meanings as well. Stick this onto a type of crop, and you have a ____field or ____crop.', 'The reading is the one you learned with the kanji.', NULL),
  ('00000000-0000-4000-8000-000000006524', 'vocabulary', '田畑', '田畑', 41, 106, 'A rice paddy field. You''d think this would refer only to a rice field, but it actually refers to other types of fields too, making this word simply field. I guess that shows how important rice is, because if a field isn''t growing rice, it ain''t no field o'' mine.', 'The readings come from what you learned with the kanji. 畑 uses the shorter はた reading that you learned.', NULL),
  ('00000000-0000-4000-8000-000000006525', 'vocabulary', '麦畑', '麦畑', 41, 107, 'A wheat field is a wheat field or barley field', 'The readings are the kun''yomi readings, but they''re also the readings you learned with the kanji. Watch out for the rendaku.', NULL),
  ('00000000-0000-4000-8000-000000006526', 'vocabulary', '包む', '包む', 41, 108, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya membungkus jadi versi vocab verbanya adalah membungkus.', 'You never wrap things once, you always wrap them twice. And then you double that. It''s a two two (つつ) wrapping technique.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000006681', 'vocabulary', '刷る', '刷る', 43, 71, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya mencetak jadi versi vocab verbanya adalah mencetak.', 'When you print something out, it''s usually the paperwork needed in order to sue (す) someone. You''re just that kind of person, always looking to sue.', NULL),
  ('00000000-0000-4000-8000-000000006682', 'vocabulary', '明朗', '明朗', 43, 72, 'Terang terang adalah sesuatu yang terang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006683', 'vocabulary', '朗報', '朗報', 43, 73, 'Laporan berita yang cerah akan menjadi berita yang penuh dengan kabar baik. Laporan berita kelam mungkin merupakan berita buruk, tetapi saat ini kita hanya peduli pada kabar baik, bukan?', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006684', 'vocabulary', '朗らか', '朗らか', 43, 74, 'Ini adalah versi kata sifat na dari terang. Kata itu cerah atau ceria.', 'Of all the people who are bright and cheerful, one man comes to mind. The cheerful Hulk Hogan (ほが).', NULL),
  ('00000000-0000-4000-8000-000000006685', 'vocabulary', '潮', '潮', 43, 75, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Since this word is made up of a single kanji, it probably uses the kun''yomi reading. You did not learn this reading, so here''s a mnemonic to help you to remember: If you think of the tide, you think of the ocean. If you think of the ocean and what it''s filled with (besides water) you think of salt (しお).', NULL),
  ('00000000-0000-4000-8000-000000006686', 'vocabulary', '風潮', '風潮', 43, 76, 'Pasang angin adalah arah bertiupnya air pasang. Apakah itu bertiup masuk? Apakah itu meledak? Ini adalah pasang surut dan arus. Saat ini, kita biasanya menggunakan kata ini untuk tren terkini yang datang seperti air pasang.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006687', 'vocabulary', '満潮', '満潮', 43, 77, 'Air pasang penuh (full tide) adalah air pasang atau air pasang penuh. Saat itulah air muncul.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006688', 'vocabulary', '潮流', '潮流', 43, 78, 'Aliran pasang surut adalah aliran yang melewati air pasang. Itu adalah air pasang atau arus pasang surut.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006689', 'vocabulary', '即〜', '即〜', 43, 79, 'Jika Anda melihat 即 sebelum sebuah kata, Anda tahu bahwa itu mungkin sesuatu yang terjadi sangat cepat atau seketika. Makanya ini bersifat instant atau instan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006690', 'vocabulary', '即興', '即興', 43, 80, 'Ketertarikan instan pada sesuatu yang sebelumnya tidak Anda minati? Nah, saatnya untuk berimprovisasi, karena Anda harus berpura-pura tertarik (padahal sebenarnya tidak).', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Watch out for the shortening of そく.', NULL),
  ('00000000-0000-4000-8000-000000006691', 'vocabulary', '即座', '即座', 43, 81, 'Duduk instan segera dilakukan. Ini juga terjadi seketika. Bayangkan saja diri Anda langsung duduk. Tidak ada waktu berlalu antara saat Anda berdiri dan duduk. Sifat duduk Anda yang seketika pasti... meresahkan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006692', 'vocabulary', '即死', '即死', 43, 82, 'Kematian instan adalah kematian instan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006693', 'vocabulary', '即日', '即日', 43, 83, 'Hari instan adalah hari yang terjadi pada saat ini juga. Ini hari yang sama seperti sekarang.', 'The reading for 即 is the normal one. For 日 you''re going to want to use the じつ reading, because, the truth (じつ) is that it''s the same day today.', NULL),
  ('00000000-0000-4000-8000-000000006694', 'vocabulary', '即効', '即効', 43, 84, 'Ini langsung efektif! Kedengarannya seperti sesuatu yang keluar dari Pokemon. Kata ini berarti efek segera atau efek instan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Watch out for the shortening.', NULL),
  ('00000000-0000-4000-8000-000000006695', 'vocabulary', '垣', '垣', 43, 85, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000006881', 'vocabulary', '脚本', '脚本', 45, 75, 'Buku kaki hanyalah kaki dari sebuah buku. Bukan keseluruhan buku. Ini hanya berisi bagian-bagian yang berjalan dan bergerak, tidak begitu banyak deskripsinya (benda yang tidak bergerak). Buku semacam ini adalah naskah atau skenario. "Buku-buku" ini berfokus pada tindakan dan perkataan orang, itulah mengapa ini hanyalah kaki.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006882', 'vocabulary', '可也', '可也', 45, 76, 'Mungkin saja jumlahnya cukup besar. Ini sangat, adil, dan cukup... sesuatu. Perlu diketahui juga bahwa ini hampir selalu ditulis dalam kana dan bukan kanji. Tapi, kita sedang belajar kanji di sini, jadi astaga kita akan belajar beberapa kanji.', 'The reading is the same as the reading you learned with the kanji.', NULL),
  ('00000000-0000-4000-8000-000000006883', 'vocabulary', '井戸', '井戸', 45, 77, 'Pintu sumur hanyalah sebuah sumur. Pintu itulah yang masuk ke dalam lubang sumur sehingga menjadi sumur.', 'This kanji uses the kun''yomi readings for each kanji, for some reason. You learned the kun''yomi reading for 戸, but in this case it''s rendaku''d so it becomes ど instead of と. You didn''t learn the kun''yomi version of 井 with the kanji. Think of this well, and look inside. There you see an eagle (い), stuck inside. As you pull it out, it scratches your eyes out.', NULL),
  ('00000000-0000-4000-8000-000000006884', 'vocabulary', '天井', '天井', 45, 78, 'Sumur surga adalah sumur yang naik ke langit. Ini berada di atas Anda, dan ini adalah langit-langit. Mungkin bagian "sumur" mengacu pada cerobong asap yang naik melalui langit-langit ke langit ketika Anda melihat ke dalam sebuah rumah yang sangat tua?', 'This is a jukugo word that uses the on''yomi readings of the kanji. You should be able to read this on your own. Be careful of the rendaku.', NULL),
  ('00000000-0000-4000-8000-000000006885', 'vocabulary', '呪い', '呪い', 45, 79, 'Despite looking like an adjective this is a noun. It means the same thing as the kanji: curse.', 'The reading is the same as the reading you learned with the kanji.', NULL),
  ('00000000-0000-4000-8000-000000006886', 'vocabulary', '呪う', '呪う', 45, 80, 'Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means curse, and the verb version is to curse or to put a curse on.', 'Bacaannya sama dengan yang Anda pelajari dengan kanji.', NULL),
  ('00000000-0000-4000-8000-000000006887', 'vocabulary', '暦', '暦', 45, 81, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'When looking at a calendar, the 子読み (こよみ) of it is to... well... not be able to read it at all. Because, children can''t really read. So, when you look at a calendar you have to explain it to a child, since they cannot read it.', NULL),
  ('00000000-0000-4000-8000-000000006888', 'vocabulary', '旧暦', '旧暦', 45, 82, 'Kalender sebelumnya adalah kalender sebelumnya. Ini adalah kalender lunisolar dan kalender tradisional Jepang. Tentu saja bukan kalender saat ini.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006889', 'vocabulary', '西暦', '西暦', 45, 83, 'Kalender Barat menunjukkan sejarah dan periode waktu "Barat". Bagi orang Jepang dan Cina, zaman ini dikenal dengan sebutan Era Kristen. Dulu juga digunakan sebagai cara untuk merujuk pada Kalender Barat, meskipun saat ini kita biasanya hanya mengucapkan カレンダー.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000006890', 'vocabulary', '曇る', '曇る', 45, 84, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya mendung dan versi vocab verbanya artinya mendung atau mendung.', 'The reading is the same as the one you learned with the kanji. It also happens to be the same as 雲, which has a very similar meaning (clouds).', NULL),
  ('00000000-0000-4000-8000-000000006891', 'vocabulary', '曇り', '曇り', 45, 85, 'Versi kata benda berawan adalah cuaca mendung atau mendung. Dalam beberapa kasus, ini juga merujuk pada jenis kabut yang Anda temukan di jendela atau kacamata Anda.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000007082', 'vocabulary', '哀れ', '哀れ', 47, 66, 'Jika ada sesuatu yang menyedihkan maka Anda patut mengasihaninya. Anda juga harus merasakan sedikit kesedihan dan kesedihan karenanya, karena sungguh, menyedihkan!', 'You look at the thing you''re feeling is so pathetic that you feel pity for and just think... aww (あわ), that''s really pathetic.', NULL),
  ('00000000-0000-4000-8000-000000007083', 'vocabulary', '可哀想', '可哀想', 47, 67, 'Sebuah konsep yang mungkin menyedihkan. Sejujurnya, ini mungkin tidak menyedihkan. Sungguh menyedihkan dan menyedihkan.', 'This is a jukugo word that uses the on''yomi readings of the kanji. Well, at least most of it does. To remember the reading for 哀 imagine some pathetic person who lost their home. They may be pitiful but at some point after losing their home they decided that the hood of your car would make a fine place to live. You can''t help but ask them, "Why (わい) my car?" There are so many other cars this pathetic person could be camping out on, but they chose yours.', NULL),
  ('00000000-0000-4000-8000-000000007084', 'vocabulary', '悲哀', '悲哀', 47, 68, 'Aku sedih dan menyedihkan dengan apa yang aku rasakan. Duka yang begitu mendalam! Duka yang begitu besar karena perasaanku yang sedih dan menyedihkan.', 'Ini adalah kata jukugo yang biasanya berarti pembacaan kanji on''yomi. Jika Anda mengetahui pembacaan kanji Anda, Anda juga akan mengetahui cara membacanya.', NULL),
  ('00000000-0000-4000-8000-000000007085', 'vocabulary', '唇', '唇', 47, 69, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Bacaannya sama dengan yang Anda pelajari dengan kanji.', NULL),
  ('00000000-0000-4000-8000-000000007086', 'vocabulary', '下唇', '下唇', 47, 70, 'Bibir bawah adalah bibir bawah atau bibir bawah Anda.', 'したくちびる is the vocab reading for 下 and the reading you learned with the kanji for 唇. This is how you''d usually read this word.
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000007289', 'vocabulary', '草刈り', '草刈り', 49, 65, 'Mari kita ambil rumputnya dan pangkasnya. Ini disebut memotong.', 'The reading is 草 and 刈 put together into one. The か reading for 刈り comes from the kanji''s reading.', NULL),
  ('00000000-0000-4000-8000-000000007290', 'vocabulary', '刈り取る', '刈り取る', 49, 66, 'Jika Anda memangkas dan mengambil dari apa yang Anda pangkas, Anda akan memotong atau menuai atau memanen apa pun yang Anda pangkas.', 'The reading is the reading you learned with 刈 and the reading from the vocab 取る.', NULL),
  ('00000000-0000-4000-8000-000000007291', 'vocabulary', '剛健', '剛健', 49, 67, 'Ketika Anda kokoh dan sehat, Anda penuh semangat dan kejantanan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007292', 'vocabulary', '唯', '唯', 49, 68, 'Kanji artinya semata-mata, dan ini artinya semata-mata, tetapi juga hal-hal terkait lainnya seperti hanya atau semata-mata. Semuanya cukup dekat, jadi cobalah mengingat beberapa!', 'To spice up something you''d describe with words like only and simply use Ta da! (ただ) to spice it up. It''s like magic! Now it isn''t just a gift, it''s a TA DA surprise gift.', NULL),
  ('00000000-0000-4000-8000-000000007293', 'vocabulary', '唯一', '唯一', 49, 69, 'Itu hanya satu. Satu satunya. Satu-satunya. Benar-benar unik.', 'The reading for 唯 is the same as the one you learned with the kanji, though there is also a shortened version which has ゆい shortened to ゆ. The reading for 一 is one you haven''t learned yet, wow! You''re finally going to learn the second, rare on''yomi reading for 一! It wants to be the only reading now, so it eats (いつ) the other one. Oh no, you can''t remember that other reading now. いつ is the sole 一 reading in your brain!', NULL),
  ('00000000-0000-4000-8000-000000007294', 'vocabulary', '唯物論', '唯物論', 49, 70, 'Teori satu-satunya hal adalah teori bahwa hanya hal-hal yang penting. Ini juga dikenal sebagai materialisme.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007295', 'vocabulary', '壇', '壇', 49, 71, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Bacaannya sama dengan yang Anda pelajari dengan kanji.', NULL),
  ('00000000-0000-4000-8000-000000007296', 'vocabulary', '花壇', '花壇', 49, 72, 'Podium bunga adalah podium bunga yang dipasang lebih tinggi dari tanah. Ini adalah hamparan bunga.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007297', 'vocabulary', '仏壇', '仏壇', 49, 73, 'Podium buddha adalah podium tempat Anda meletakkan Buddha. Ini adalah altar Buddha.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007298', 'vocabulary', '尼僧', '尼僧', 49, 74, 'Seorang biarawati pendeta adalah seorang biarawati atau pendeta wanita.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007299', 'vocabulary', '尼', '尼', 49, 75, 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Are you a nun? I am a (あま) nun.', NULL),
  ('00000000-0000-4000-8000-000000007300', 'vocabulary', '気概', '気概', 49, 76, 'Semangat pendekatan adalah pendekatan roh. Perkiraan saya terhadap semangat Anda? Saya pikir Anda memiliki semangat yang kuat. Saya pikir Anda memiliki tulang punggung.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007301', 'vocabulary', '概算', '概算', 49, 77, 'Perkiraan perhitungan merupakan perkiraan atau perkiraan kasar.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007302', 'vocabulary', '概念', '概念', 49, 78, 'Perkiraan pemikiran hanyalah memikirkan gagasan umum. Konsep atau gagasan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007303', 'vocabulary', '概要', '概要', 49, 79, 'Perkiraan tentang apa yang kita butuhkan adalah garis besar/ringkasan saya.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007304', 'vocabulary', '大概', '大概', 49, 80, 'Perkiraan besarnya adalah ketika saya mengatakan sesuatu secara umum. Saya terutama dan sebagian besar menceritakan semuanya.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007305', 'vocabulary', '一概に', '一概に', 49, 81, 'Kami bergerak menuju satu perkiraan. Dulunya lebih banyak perkiraan, tapi sekarang hanya satu, dan karena hanya satu, maka sebenarnya bukan perkiraan lagi. Itu sudah diatur tanpa syarat. Itu sudah ditetapkan sebagai aturan.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007306', 'vocabulary', '浸る', '浸る', 49, 82, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanji sendiri artinya terbenam. Hal-hal yang dibenamkan digambarkan dengan kata kerja seperti direndam atau ditenggelamkan atau dibanjiri.', 'What is soaked and submerged in water (that shouldn''t be)? It is your heater (ひた). It''s all soaked and doesn''t work anymore :(', NULL),
  ('00000000-0000-4000-8000-000000007307', 'vocabulary', '浸水', '浸水', 49, 83, 'Dicelupkan ke dalam air. Kedengarannya seperti tenggelam. Bahkan mungkin seperti banjir.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007308', 'vocabulary', '侵食', '侵食', 49, 84, 'Sesuatu yang menyerang dan menggerogoti sesuatu adalah sesuatu yang menyebabkan erosi dan korosi.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007309', 'vocabulary', '淡い', '淡い', 49, 85, 'Ini adalah kanji tunggal dengan い di akhir, artinya Anda tahu itu mungkin kata sifat. Apa bentuk kata sifat pingsan? Itu samar.', 'You look at the distance. You see something very faint and pale out there. It''s... it''s... awwwa (あわ) a puppy! Awwwww! Aawwww!', NULL),
  ('00000000-0000-4000-8000-000000007310', 'vocabulary', '淡水', '淡水', 49, 86, 'Air yang lemah adalah air yang tidak kental dengan garam. Itu air tawar.', 'Ini adalah kata jukugo yang menggunakan pembacaan kanji on''yomi. Anda seharusnya bisa membaca ini sendiri.', NULL),
  ('00000000-0000-4000-8000-000000007311', 'vocabulary', '煮る', '煮る', 49, 87, 'Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. 
INSERT INTO public.items (id, type, character, slug, level, lesson_position, meaning_mnemonic, reading_mnemonic, svg_filename) VALUES
  ('00000000-0000-4000-8000-000000008882', 'kanji', '挨', '挨', 44, 36, 'You use your fingers when you''re in private to use an arrow to push open things.', 'Your favorite thing to push open is your own eye (あい). You take the arrow into your fingers and gently push each lid open until you can see.', NULL),
  ('00000000-0000-4000-8000-000000008883', 'kanji', '拶', '拶', 44, 37, 'Your fingers told you that a flood last evening seemed to be imminent, and that there was nothing you could do to stop it. You felt it draw close, coming in the darkness of the evening.', 'As the flood began to draw close you knew there was nothing you could do, so you sat (さつ) down  and waited.', NULL),
  ('00000000-0000-4000-8000-000000008886', 'kanji', '凄', '凄', 41, 34, 'Your ice wife is amazing. She''s also terrible, because she''s very cold and has many ice powers, but that''s also part of what makes her amazing!', 'She turns her amazing gaze onto your saber (せい) and hits it with an ice beam. Woah! Instead of turning to ice or shattering, it steals her awful powers. Now your saber is amazing and terrible too!', NULL),
  ('00000000-0000-4000-8000-000000008890', 'vocabulary', '慌てる', '慌てる', 49, 141, 'This word consists of kanji with hiragana attached. Because the hiragana ends with an う sound, you know this word is a verb. The kanji itself means confused or bewildered but this is usually just used when someone starts to panic. They''re so confused and bewildered that they try to hurry through things.', 'Since this word consists of a kanji with hiragana attached, you can bet that it will use the kun''yomi reading. You haven''t learned this reading yet, so here''s a mnemonic to help you:
